function normalizeCatalogText(value = '') {
  return stripEmoji(String(value || '').toLowerCase())
}

function classifyCatalogItem(item, type = 'game') {
  if (item?.catalog_type) return item.catalog_type

  const cat = String(item?.category || '').toLowerCase()
  const delType = String(item?.delivery_type || '').toLowerCase()
  const pType = String(item?.provider_type || '').toLowerCase()

  // 1. Direct category matches
  if (cat === 'game_account' || delType === 'game_account') return 'game-accounts'
  if (cat === 'subscription') return 'subscription'
  if (cat === 'topup' || cat === 'direct-topup' || cat === 'direct_topup' || delType === 'id_topup') return 'direct-topup'
  if (cat === 'code' || cat === 'game-cdkey' || cat === 'cdkey' || cat === 'license' || delType === 'code' || delType === 'key') return 'game-cdkey'
  if (cat === 'card' || cat === 'giftcard') return 'card'
  if (cat === 'game-cards' || cat === 'game_card') return 'game-cards'
  if (cat === 'mobile-game-cards') return 'mobile-game-cards'
  if (cat === 'game-console') return 'game-console'
  if (cat === 'game-accounts' || cat === 'game_accounts') return 'game-accounts'

  // 2. Automated provider type
  if (pType === 'topup' || pType === 'steam_topup') return 'direct-topup'
  if (pType === 'giftcard') return 'card'
  if (pType === 'gamekey') return 'game-cdkey'

  // 3. Text heuristics on name, title, description, account_game
  const text = normalizeCatalogText(`${item?.title || ''} ${item?.name || ''} ${item?.description || ''} ${item?.account_game || ''}`)

  // Subscriptions: Streaming, AI, Music, Nitro
  if (/discord nitro|nitro|chatgpt|openai|\bgpt\b|claude|gemini|midjourney|netflix|spotify|disney|prime video|amazon prime|crunchyroll|youtube premium|\bmax\b|paramount|deezer|tidal|applemusic|apple music|canva|office 365|suscripci[oó]n|membres[ií]a/.test(text)) return 'subscription'

  // Digital services / connectivity
  if (/airalo|esim|telegram premium|bot\b|smm|sms|vpn/.test(text)) return 'digital-service'

  // Direct Top-up
  if (/top\s*-?\s*up|recarga|diamantes|diamonds|robux|free fire|blood strike|mobile legends|pubg|uc\b|cp\b|coins\b|saldo movil|saldo móvil/.test(text)) return 'direct-topup'

  // Game CD-Keys / Licenses
  if (/cd\s*-?\s*key|\bkey\b|clave digital|licencia|license|windows 10|windows 11|antivirus|steam key|epic key|xbox code/.test(text)) return 'game-cdkey'

  // Game console specific
  if (/xbox global games|nintendo games|global games|xbox:|playstation|psn|nintendo|switch|console|consola/.test(text)) return 'game-console'

  // Mobile game cards
  if (/mobile|ios|android/.test(text) && /card|gift|tarjeta/.test(text)) return 'mobile-game-cards'

  // Game cards
  if (/game card|gaming card|tarjeta.*juego|juego.*tarjeta|roblox card|razer gold|garena shells|cherry credits/.test(text)) return 'game-cards'

  // General cards / Giftcards
  if (/apple|app store|google play|amazon|steam gift|gift card|tarjeta de regalo|tarjeta regalo|eneba|jd\.com|walmart|neosurf|culture land|payeer|vanilla visa|visa vanilla|mastercard|transcash|rewarble|voucher|wallet/.test(text)) return 'card'

  // Game account heuristics
  if (item?.account_game || item?.account_platform || (type === 'manual' && cat === 'account')) return 'game-accounts'

  if (type === 'manual') {
    return 'digital-service'
  }

  return 'game'
}

