function SmsNumbersScreen({ me, onBack, onLoginRequired, onBought }) {
  const initialSmsParams = useRef(null)
  if (!initialSmsParams.current) {
    const params = new URLSearchParams(window.location.search)
    initialSmsParams.current = {
      country: params.get('sms_country') || '',
      service: params.get('sms_service') || '',
      operator: params.get('sms_operator') || 'any',
    }
  }
  const [settings, setSettings] = useState(null)
  const [countries, setCountries] = useState([])
  const [services, setServices] = useState([])
  const [operators, setOperators] = useState([])
  const [country, setCountry] = useState(initialSmsParams.current.country)
  const [service, setService] = useState('')
  const [operator, setOperator] = useState(initialSmsParams.current.operator || 'any')
  const [activePicker, setActivePicker] = useState('country')
  const [loading, setLoading] = useState(true)
  const [loadingStep, setLoadingStep] = useState(false)
  const [buying, setBuying] = useState(false)
  const [err, setErr] = useState(null)
  const [order, setOrder] = useState(null)
  const [countryQuery, setCountryQuery] = useState('')
  const [serviceQuery, setServiceQuery] = useState('')
  const [operatorsOpen, setOperatorsOpen] = useState(false)
  const [showShare, setShowShare] = useState(false)
  const [showDripHelp, setShowDripHelp] = useState(false)
  const [canceling, setCanceling] = useState(false)
  const [nowSec, setNowSec] = useState(() => Math.floor(Date.now() / 1000))

  useEffect(() => {
    if (!order || order.code || order.status === 'canceled' || order.status === 'failed') return
    const timer = setInterval(() => {
      setNowSec(Math.floor(Date.now() / 1000))
    }, 1000)
    return () => clearInterval(timer)
  }, [order?.id, order?.code, order?.status])

  useEffect(() => {
    if (!order || order.status === 'completed' || order.status === 'canceled' || order.code) return
    const idToPoll = order.id_5sim || order.fivesim_order_id || order.id
    if (!idToPoll) return
    const interval = setInterval(async () => {
      try {
        const res = await api.smsOrderStatus(idToPoll)
        if (res?.ok && res?.order) {
          const ord = res.order
          if (ord.code) {
            setOrder(prev => ({ ...prev, ...ord, code: ord.code }))
          } else if (ord.status === 'canceled' || ord.status === 'failed') {
            setOrder(prev => ({ ...prev, ...ord }))
          }
        }
      } catch {}
    }, 3500)
    return () => clearInterval(interval)
  }, [order?.id, order?.id_5sim, order?.status, order?.code])

  useEffect(() => {
    setLoading(true); setErr(null)
    Promise.all([api.smsSettingsGet().catch(() => null), api.smsCountries()])
      .then(([cfg, data]) => {
        setSettings(cfg)
        setCountries(data.items || [])
        setActivePicker(initialSmsParams.current.country ? 'service' : 'country')
      })
      .catch(e => setErr(`Error al cargar países: ${e.message}`))
      .finally(() => setLoading(false))
  }, [])

  useEffect(() => {
    if (!country) return
    setLoadingStep(true); setErr(null); setServices([]); setOperators([]); setService(''); setOperator('any'); setServiceQuery('')
    api.smsServices(country).then(data => {
      const items = data.items || []
      setServices(items)
      const initialService = initialSmsParams.current.service
      if (initialService && items.some(item => item.key === initialService)) {
        setService(initialService)
        setActivePicker(null)
      } else {
        setActivePicker('service')
      }
    }).catch(e => setErr(`Error al cargar aplicaciones: ${e.message}`)).finally(() => setLoadingStep(false))
  }, [country])

  useEffect(() => {
    if (!country || !service) return
    setLoadingStep(true); setErr(null); setOperators([]); setOperator('any')
    api.smsOperators(country, service).then(data => setOperators(data.items || []))
      .catch(e => setErr(`Error al cargar operadores: ${e.message}`)).finally(() => setLoadingStep(false))
  }, [country, service])

  const selectedCountry = countries.find(x => x.key === country)
  const selectedService = services.find(x => x.key === service)
  const selectedOperator = operator === 'any' ? null : operators.find(x => x.name === operator)
  const bestOperator = operators[0]
  const price = Number(selectedOperator?.price || bestOperator?.price || selectedService?.price || 0)
  const stock = Number((operator === 'any' ? operators.reduce((sum, op) => sum + Number(op.qty || 0), 0) : selectedOperator?.qty) || selectedService?.qty || 0)
  const filteredCountries = countries.filter(c => !countryQuery || `${c.name} ${c.key}`.toLowerCase().includes(countryQuery.toLowerCase()))
  const filteredServices = services.filter(x => !serviceQuery || `${x.name} ${x.key}`.toLowerCase().includes(serviceQuery.toLowerCase()))
  const smsShareParams = new URLSearchParams({ screen: 'sms' })
  if (country) smsShareParams.set('sms_country', country)
  if (service) smsShareParams.set('sms_service', service)
  if (operator && operator !== 'any') smsShareParams.set('sms_operator', operator)
  const smsShareLink = `${window.location.origin}${window.location.pathname}?${smsShareParams.toString()}`
  const smsShareName = selectedCountry || selectedService ? `Números virtuales${selectedService ? ' para ' + selectedService.name : ''}${selectedCountry ? ' en ' + selectedCountry.name : ''}` : 'Números virtuales SMS'

  async function buy() {
    if (me?.is_guest) { onLoginRequired?.(); return }
    if (!country || !service) return
    setBuying(true); setErr(null)
    try {
      const data = await api.smsOrderCreate({ country, service, operator })
      setOrder(data)
      onBought?.(data)
    } catch (e) {
      setErr(e.message)
    }
    setBuying(false)
  }

  return (
    <div className="h-[100dvh] flex flex-col bg-bg overflow-hidden">
      {showShare && <ShareProductModal shareLink={smsShareLink} productName={smsShareName} onClose={() => setShowShare(false)} />}
      <div className="flex-shrink-0 border-b border-white/5 bg-bg/95 p-3.5 backdrop-blur">
        <div className="mx-auto flex max-w-lg items-center gap-3">
          <button onClick={onBack} className="flex h-9 w-9 items-center justify-center rounded-full bg-card border border-white/10 active:scale-90 transition" aria-label="Volver">
            <ArrowLeft className="h-4 w-4 text-white" />
          </button>
          <h1 className="min-w-0 flex-1 text-base font-black text-white">Números Virtuales</h1>
          <button onClick={() => setShowShare(true)} className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-full border border-violet-400/35 bg-violet-500/15 text-violet-200 active:scale-90 transition" aria-label="Compartir números virtuales">
            <Share2 className="h-4 w-4" />
          </button>
        </div>
      </div>

      <main className="mx-auto flex w-full max-w-lg flex-1 flex-col overflow-hidden px-3 pt-3">
        {loading ? (
          <div className="flex flex-1 flex-col overflow-hidden min-h-0 space-y-3 animate-pulse">
            <div className="h-28 rounded-xl bg-card/60" />
            <div className="grid grid-cols-2 gap-2">
              <div className="h-12 rounded-xl bg-card/60" />
              <div className="h-12 rounded-xl bg-card/60" />
            </div>
            <div className="flex-1 rounded-xl bg-card/40 min-h-[160px]" />
          </div>
        ) : (
          <div className="flex flex-1 flex-col overflow-hidden min-h-0">
            <div className="flex-shrink-0">
              <section className="mb-3 overflow-hidden rounded-xl border border-white/10 bg-card">
                <div className="relative min-h-[112px] bg-[#101820]">
                  {settings?.sms_catalog_image_url ? <OptimizedImage src={storeAssetUrl(settings.sms_catalog_image_url)} alt="" className="absolute inset-0 h-full w-full object-cover" /> : <div className="absolute inset-0 bg-gradient-to-br from-cyan-500/20 via-bg to-emerald-500/10" />}
                  <div className="absolute inset-0 bg-gradient-to-r from-black/90 via-black/65 to-black/35" />
                  <div className="relative flex h-full min-h-[112px] items-center p-4">
                    <div className="space-y-1.5">
                      <p className="text-xs leading-relaxed text-white/80">
                        Compra números virtuales de diferentes países para recibir códigos de verificación al instante. El código llegará directamente a tus pedidos de forma automática. Obtén reembolso garantizado si el SMS no llega o si decides cancelar el pedido.
                      </p>
                      {me?.reseller_tier?.tier_id && me?.reseller_tier?.tier_id !== 'standard' && (
                        <div className="inline-flex items-center gap-1.5 rounded-full bg-accent/20 border border-accent/40 px-2.5 py-0.5 text-[11px] font-black text-accent shadow-sm">
                          <span>💼 Precios Mayoristas Activos:</span>
                          <span className="text-white">{me.reseller_tier.badge}</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </section>
              <section className="mb-3 grid grid-cols-2 gap-2">
                <button onClick={() => setActivePicker('country')} className={`flex min-w-0 items-center gap-2 rounded-xl border px-2.5 py-2 text-left active:scale-[0.99] ${activePicker === 'country' ? 'border-accent bg-accent/10' : 'border-white/10 bg-card'}`}>
                  <span className="flex h-8 w-8 flex-shrink-0 overflow-hidden rounded-lg bg-black/20 text-base"><SmsIcon src={smsCountryIconUrl(selectedCountry)} fallback={<span>{selectedCountry?.flag_emoji || '🌐'}</span>} /></span>
                  <span className="min-w-0"><span className="block text-[10px] uppercase text-white/35">País</span><span className="block truncate text-xs font-black">{selectedCountry?.name || 'Escoger país'}</span></span>
                </button>
                <button onClick={() => country && setActivePicker('service')} disabled={!country} className={`flex min-w-0 items-center gap-2 rounded-xl border px-2.5 py-2 text-left active:scale-[0.99] disabled:opacity-50 ${activePicker === 'service' ? 'border-accent bg-accent/10' : 'border-white/10 bg-card'}`}>
                  <span className="flex h-8 w-8 flex-shrink-0 overflow-hidden rounded-lg bg-black/20"><SmsIcon src={smsServiceIconUrl(selectedService || {})} fallback={<Smartphone className="h-4 w-4 text-cyan-200" />} fit="contain" /></span>
                  <span className="min-w-0"><span className="block text-[10px] uppercase text-white/35">App</span><span className="block truncate text-xs font-black">{selectedService?.name || 'Escoger app'}</span></span>
                </button>
              </section>
            </div>

            {loadingStep && <div className="mb-3 flex justify-center flex-shrink-0"><Loader2 className="h-4 w-4 animate-spin text-accent" /></div>}

            <div className="flex-1 overflow-hidden min-h-0 flex flex-col">
              {activePicker === 'country' && (
                <section className="flex flex-1 flex-col overflow-hidden rounded-xl border border-white/10 bg-card">
                  <div className="border-b border-white/10 p-3 flex-shrink-0">
                    <div className="mb-2 flex items-center justify-between"><p className="text-sm font-black">Escoger país</p><span className="text-[10px] text-white/40">{filteredCountries.length}</span></div>
                    <div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/35" /><input value={countryQuery} onChange={e => setCountryQuery(e.target.value)} placeholder="Buscar país" className="w-full rounded-lg border border-white/10 bg-bg py-2.5 pl-9 pr-3 text-sm outline-none focus:border-accent" /></div>
                  </div>
                  <div className="overflow-y-auto p-3 pb-28 flex-1 min-h-0">
                    <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
                      {filteredCountries.map(c => (
                        <button
                          key={c.key}
                          onClick={() => { setCountry(c.key); setCountryQuery('') }}
                          className={`min-w-0 overflow-hidden rounded-xl border p-2 text-left active:scale-[0.99] ${country === c.key ? 'border-accent bg-accent/12' : 'border-white/10 bg-bg/70 hover:border-white/20'}`}
                        >
                          <span className="flex items-center gap-2 min-w-0">
                            <span className="flex h-9 w-9 flex-shrink-0 overflow-hidden rounded-lg border border-white/10 bg-black/20 text-lg">
                              <SmsIcon src={smsCountryIconUrl(c)} fallback={<span>{c.flag_emoji || '🌐'}</span>} />
                            </span>
                            <span className="min-w-0 flex-1">
                              <span className="block truncate text-xs font-black">{c.name}</span>
                              <span className="block text-[10px] uppercase text-white/35">{c.key}</span>
                            </span>
                          </span>
                        </button>
                      ))}
                    </div>
                  </div>
                </section>
              )}

              {activePicker === 'service' && (
                <section className="flex flex-1 flex-col overflow-hidden rounded-xl border border-white/10 bg-card">
                  <div className="border-b border-white/10 p-3 flex-shrink-0">
                    <div className="mb-2 flex items-center justify-between"><div><p className="text-sm font-black">Escoger app</p><p className="text-[11px] text-white/45">{selectedCountry?.name || ''}</p></div><span className="text-[10px] text-white/40">{filteredServices.length}</span></div>
                    <div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/35" /><input value={serviceQuery} onChange={e => setServiceQuery(e.target.value)} placeholder="Buscar app" className="w-full rounded-lg border border-white/10 bg-bg py-2.5 pl-9 pr-3 text-sm outline-none focus:border-accent" /></div>
                  </div>
                  <div className="overflow-y-auto p-3 pb-28 flex-1 min-h-0">
                    <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
                      {filteredServices.map(x => <button key={x.key} onClick={() => { setService(x.key); setServiceQuery(''); setActivePicker(null) }} className={`rounded-xl border p-2.5 text-left active:scale-[0.99] ${service === x.key ? 'border-accent bg-accent/12' : 'border-white/10 bg-bg/70 hover:border-white/20'}`}><span className="flex items-center gap-3"><span className="flex h-10 w-10 flex-shrink-0 overflow-hidden rounded-xl border border-white/10 bg-black/20"><SmsIcon src={smsServiceIconUrl(x)} fallback={<span className="text-sm font-black text-cyan-200">{(x.name || x.key || '?')[0]?.toUpperCase()}</span>} fit="contain" /></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-black">{x.name}</span><span className="block text-[11px] text-white/40">{x.qty} disponibles</span></span><span className="text-right flex flex-col items-end flex-shrink-0">{x.price_max && Number(x.price_max) > Number(x.price) ? <span className="text-xs sm:text-sm font-black text-accent whitespace-nowrap">Desde ${Number(x.price || 0).toFixed(2)} hasta ${Number(x.price_max).toFixed(2)}</span> : <span className="text-sm font-black text-accent whitespace-nowrap">${Number(x.price || 0).toFixed(2)}</span>}</span></span></button>)}
                    </div>
                    {!loadingStep && services.length === 0 && <p className="rounded-lg bg-bg p-4 text-center text-xs text-white/45">No hay apps disponibles para este país.</p>}
                  </div>
                </section>
              )}

              {!activePicker && (
                <section className="rounded-xl border border-white/10 bg-card p-3">
                  <button onClick={() => setOperatorsOpen(true)} disabled={!service || operators.length === 0} className="flex w-full items-center justify-between gap-3 rounded-lg bg-bg/70 px-3 py-3 text-left active:scale-[0.99] disabled:opacity-50">
                    <span className="min-w-0">
                      <span className="block text-[10px] font-bold uppercase text-white/35">Operador</span>
                      <span className="block truncate text-sm font-black">{operator === 'any' ? 'Automático' : operator}</span>
                      <span className="block truncate text-[11px] text-white/45">{operators.length || 0} opciones disponibles</span>
                    </span>
                    <ChevronDown className="h-5 w-5 flex-shrink-0 text-accent" />
                  </button>
                </section>
              )}

              {err && <p className="mt-3 rounded-lg border border-red-500/25 bg-red-500/10 p-3 text-xs font-semibold text-red-300">{err}</p>}
              {order && (
                <div className="mt-3 rounded-xl border border-accent/30 bg-card/95 p-3.5 text-xs shadow-lg space-y-2.5">
                  <div className="flex items-center justify-between">
                    <span className="font-black text-accent text-sm flex items-center gap-1.5">
                      <Smartphone className="h-4 w-4 text-accent" />
                      {order.code ? '¡Código SMS recibido!' : 'Número reservado'}
                    </span>
                    <span className="rounded bg-white/10 px-2 py-0.5 text-[10px] font-bold uppercase text-white/70">{order.service || selectedService?.name || 'SMS'}</span>
                  </div>
                  <div className="flex items-center justify-between rounded-lg bg-black/40 p-2 border border-white/5">
                    <div>
                      <p className="text-[10px] text-white/40 uppercase font-semibold">Número de teléfono</p>
                      <p className="font-mono text-base font-black text-white select-all">{order.phone}</p>
                    </div>
                    <button
                      type="button"
                      onClick={() => navigator.clipboard.writeText(order.phone)}
                      className="rounded-lg bg-white/10 px-3 py-1.5 text-xs font-bold text-white hover:bg-white/20 active:scale-95"
                    >
                      Copiar
                    </button>
                  </div>
                  {order.code ? (
                    <div className="flex items-center justify-between rounded-lg bg-emerald-500/20 p-3 border border-emerald-500/40 animate-in zoom-in-95 duration-200">
                      <div>
                        <p className="text-[10px] text-emerald-300 font-bold uppercase">Código de verificación</p>
                        <p className="font-mono text-xl font-black text-emerald-300 tracking-wider select-all">{order.code}</p>
                      </div>
                      <button
                        type="button"
                        onClick={() => navigator.clipboard.writeText(order.code)}
                        className="rounded-lg bg-emerald-500 px-3.5 py-1.5 text-xs font-black text-black shadow-md hover:bg-emerald-400 active:scale-95"
                      >
                        Copiar Código
                      </button>
                    </div>
                  ) : order.status === 'canceled' || order.status === 'failed' || order.status === 'refunded' ? (
                    <div className="flex items-center gap-2 text-emerald-400 bg-emerald-500/10 p-3 rounded-lg border border-emerald-500/20 text-xs font-semibold">
                      <CircleCheck className="h-4 w-4 flex-shrink-0 text-emerald-400" />
                      <span>Número cancelado con éxito. Tu saldo ha sido reembolsado a tu cuenta.</span>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      <div className="flex items-center gap-2 text-amber-300 bg-amber-500/10 p-2.5 rounded-lg border border-amber-500/20">
                        <Loader2 className="h-4 w-4 animate-spin flex-shrink-0" />
                        <span className="text-[11px] font-medium">Esperando código SMS... Puedes esperar aquí o consultarlo en Mis pedidos.</span>
                      </div>
                      {(() => {
                        const createdTs = Math.floor(order.created_at || nowSec)
                        const elapsed = Math.max(0, nowSec - createdTs)
                        const remSecs = Math.max(0, 120 - elapsed)
                        const canCancel = remSecs <= 0
                        const mins = Math.floor(remSecs / 60)
                        const secs = String(remSecs % 60).padStart(2, '0')

                        return (
                          <button
                            type="button"
                            disabled={canceling}
                            onClick={async () => {
                              if (!canCancel) {
                                alert(`Las políticas del proveedor exigen esperar 2 minutos desde la reserva para poder cancelar. Tiempo restante: ${mins}:${secs} min.`);
                                return;
                              }
                              if (!window.confirm('¿Deseas cancelar este número? El saldo se devolverá a tu cuenta de inmediato.')) return;
                              setCanceling(true);
                              setErr(null);
                              try {
                                const res = await api.smsOrderCancel(order.id_5sim || order.id || order.fivesim_order_id);
                                if (res?.ok) {
                                  setOrder(prev => ({ ...prev, status: 'canceled', ...(res.order || {}) }));
                                } else {
                                  setErr(res?.message || 'No se pudo cancelar el número');
                                }
                              } catch (e) {
                                setErr(`Cancelación: ${e.message}`);
                              } finally {
                                setCanceling(false);
                              }
                            }}
                            className={`w-full rounded-xl border p-2.5 text-center text-xs font-black transition flex items-center justify-center gap-2 ${
                              canCancel
                                ? 'border-red-500/40 bg-red-500/15 text-red-300 hover:bg-red-500/25 active:scale-98 cursor-pointer'
                                : 'border-white/10 bg-white/5 text-white/50 hover:border-white/20'
                            }`}
                          >
                            {canceling ? (
                              <>
                                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                                <span>Cancelando y reembolsando...</span>
                              </>
                            ) : (
                              <>
                                <CircleX className="h-4 w-4 text-red-400" />
                                <span>{canCancel ? 'Cancelar número y recuperar saldo' : `Cancelar número (Disponible en ${mins}:${secs} min)`}</span>
                              </>
                            )}
                          </button>
                        );
                      })()}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      <div className="fixed inset-x-0 bottom-0 z-40 mx-auto max-w-lg border-t border-white/10 bg-bg/95 p-3 pb-[calc(env(safe-area-inset-bottom)+12px)] shadow-2xl shadow-black/50 backdrop-blur">
        <div className="mb-2 flex items-center justify-between gap-3">
          <div className="min-w-0"><p className="truncate text-xs font-bold text-white/80">{selectedService?.name || 'Selecciona app'}</p><p className="text-[10px] text-white/40">Stock {stock} · {operator === 'any' ? 'Operador automático' : operator}</p></div>
          <p className="text-xl font-black text-accent">${price.toFixed(2)}</p>
        </div>
        <button onClick={buy} disabled={buying || !country || !service || price <= 0} className="fs-btn-glossy w-full rounded-xl py-3 text-sm font-black text-bg disabled:opacity-50">{buying ? 'Comprando...' : 'Comprar número'}</button>
      </div>

      {operatorsOpen && (
        <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/70 p-0 backdrop-blur-sm sm:items-center sm:p-4" onClick={() => setOperatorsOpen(false)}>
          <div className="max-h-[66vh] w-full max-w-md overflow-hidden rounded-t-2xl border border-white/10 bg-card shadow-2xl sm:rounded-2xl" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between border-b border-white/10 p-4"><h3 className="text-base font-black">Seleccionar operador</h3><button onClick={() => setOperatorsOpen(false)} className="rounded-lg bg-white/8 p-2"><X className="h-4 w-4" /></button></div>
            <div className="max-h-[52vh] space-y-2 overflow-y-auto p-3">
              <button onClick={() => { setOperator('any'); setOperatorsOpen(false) }} className={`w-full rounded-xl border p-3 text-left ${operator === 'any' ? 'border-accent bg-accent/12 text-accent' : 'border-white/10 bg-bg text-white/70'}`}><span className="block font-black">Automático</span><span className="text-xs text-white/45">Mejor precio disponible · ${Number(bestOperator?.price || selectedService?.price || 0).toFixed(2)}</span></button>
              {operators.map(op => <button key={op.name} onClick={() => { setOperator(op.name); setOperatorsOpen(false) }} className={`w-full rounded-xl border p-3 text-left ${operator === op.name ? 'border-accent bg-accent/12 text-accent' : 'border-white/10 bg-bg text-white/70'}`}><span className="block truncate font-black capitalize">{op.name}</span><span className="text-xs text-white/45">{op.qty} disponibles · ${Number(op.price || 0).toFixed(2)}</span></button>)}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

