function getItemFilterableName(child) {
  if (!child) return ''
  const p = child.props || {}
  if (p.game) return p.game.title || p.game.name || ''
  if (p.product) return p.product.name || ''
  if (p.type === 'telegram') return 'Telegram Stars VIP'
  if (p.type === 'capcut') return 'CapCut Pro'
  if (child.type?.name === 'SmsCatalogCard') return 'Números Virtuales SMS OTP'
  if (child.type?.name === 'SmmCatalogCard') return 'Seguidores y Likes SMM Redes'
  return ''
}

function CatalogGridView({ title, icon: Icon, count, categoryType = 'card', children, onBack }) {
  const allItems = useMemo(() => flattenCatalogChildren(children), [children])
  const [activeChip, setActiveChip] = useState('all')
  const [query, setQuery] = useState('')
  const [sortOrder, setSortOrder] = useState('default')

  const availableChips = useMemo(() => {
    const presets = CATEGORY_FILTER_PRESETS[categoryType] || [
      { id: 'all', label: 'Todos' },
      { id: 'destacados', label: 'Destacados', match: ['free fire', 'roblox', 'playstation', 'steam', 'google', 'xbox'] },
    ]
    return presets.filter(chip => {
      if (chip.id === 'all') return true
      return allItems.some(item => {
        const name = getItemFilterableName(item).toLowerCase()
        return chip.match.some(m => name.includes(m))
      })
    })
  }, [categoryType, allItems])

  const visibleItems = useMemo(() => {
    let list = allItems.slice()
    if (activeChip !== 'all') {
      const chip = availableChips.find(c => c.id === activeChip)
      if (chip?.match) {
        list = list.filter(item => {
          const name = getItemFilterableName(item).toLowerCase()
          return chip.match.some(m => name.includes(m))
        })
      }
    }
    if (query.trim()) {
      const q = query.trim().toLowerCase()
      list = list.filter(item => getItemFilterableName(item).toLowerCase().includes(q))
    }
    if (sortOrder === 'name-asc') {
      list.sort((a, b) => getItemFilterableName(a).localeCompare(getItemFilterableName(b)))
    } else if (sortOrder === 'name-desc') {
      list.sort((a, b) => getItemFilterableName(b).localeCompare(getItemFilterableName(a)))
    }
    return list
  }, [allItems, activeChip, query, sortOrder, availableChips])

  const hasActiveFilter = activeChip !== 'all' || query.trim() !== '' || sortOrder !== 'default'

  const clearFilters = () => {
    setActiveChip('all')
    setQuery('')
    setSortOrder('default')
  }

  return (
    <section className="mb-6 [content-visibility:auto] [contain-intrinsic-size:360px]">
      <div className="mb-3 flex items-center justify-between gap-3">
        {/* Flecha de atrás en el lado izquierdo */}
        <button
          type="button"
          onClick={onBack}
          className="inline-flex flex-shrink-0 items-center gap-1.5 rounded-xl border border-white/10 bg-[#16181f] px-3.5 py-2 text-xs font-bold text-white/80 active:scale-95 hover:border-[#ffff00]/60 hover:text-white transition"
          aria-label="Volver"
        >
          <ArrowLeft className="h-3.5 w-3.5 text-[#ffff00]" />
          <span>Atrás</span>
        </button>

        {/* Título de la sección y contador en el lado derecho */}
        <div className="min-w-0 text-right">
          <h3 className="inline-flex min-w-0 items-center justify-end gap-2 text-sm font-black uppercase text-white/85">
            <Icon className="h-4 w-4 flex-shrink-0 text-[#ffff00]" />
            <span className="truncate">{title}</span>
            <span className="rounded-full bg-[#ffff00]/10 border border-[#ffff00]/25 px-2 py-0.5 text-[10px] font-black text-[#ffff00]">
              {allItems.length}
            </span>
          </h3>
          <p className="mt-0.5 text-xs text-white/40">
            {visibleItems.length === allItems.length 
              ? `${allItems.length} productos disponibles` 
              : `Mostrando ${visibleItems.length} de ${allItems.length}`}
          </p>
        </div>
      </div>

      {/* Barra de Filtros Bonoxs Style */}
      <div className="mb-3.5 space-y-2 rounded-2xl border border-white/10 bg-[#16181f]/80 p-2.5 backdrop-blur-md">
        <div className="flex items-center gap-2">
          <div className="relative flex-1">
            <Search className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-white/40" />
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder={`Buscar en ${title}...`}
              className="w-full rounded-xl border border-white/10 bg-[#101318] py-1.5 pl-8 pr-7 text-xs text-white placeholder-white/35 focus:border-[#ffff00]/80 focus:outline-none focus:ring-1 focus:ring-[#ffff00]/30 transition"
            />
            {query && (
              <button
                type="button"
                onClick={() => setQuery('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-white/40 hover:text-white"
              >
                <X className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <div className="flex-shrink-0">
            <select
              value={sortOrder}
              onChange={(e) => setSortOrder(e.target.value)}
              className="rounded-xl border border-white/10 bg-[#101318] px-2.5 py-1.5 text-xs font-bold text-white/80 focus:border-[#ffff00]/80 focus:outline-none cursor-pointer"
            >
              <option value="default">Destacados</option>
              <option value="name-asc">Nombre A-Z</option>
              <option value="name-desc">Nombre Z-A</option>
            </select>
          </div>
        </div>

        {availableChips.length > 1 && (
          <div className="flex items-center gap-1.5 overflow-x-auto pb-0.5 [scrollbar-width:none]">
            {availableChips.map(chip => {
              const active = activeChip === chip.id
              return (
                <button
                  key={chip.id}
                  type="button"
                  onClick={() => setActiveChip(chip.id)}
                  className={`flex-shrink-0 rounded-full px-2.5 py-1 text-[11px] font-bold transition-all active:scale-95 ${
                    active
                      ? 'bg-[#ffff00] text-black border border-[#ffff00] shadow-[0_2px_10px_rgba(255,255,0,0.3)]'
                      : 'bg-white/5 text-white/70 border border-white/10 hover:border-white/20 hover:text-white'
                  }`}
                >
                  {chip.label}
                </button>
              )
            })}
          </div>
        )}

        {hasActiveFilter && (
          <div className="flex items-center justify-between text-[11px] text-white/50 pt-1 border-t border-white/5">
            <span>Filtro activo</span>
            <button
              type="button"
              onClick={clearFilters}
              className="text-xs font-bold text-[#ffff00] hover:underline"
            >
              Limpiar filtros
            </button>
          </div>
        )}
      </div>

      {visibleItems.length === 0 ? (
        <div className="rounded-2xl border border-white/10 bg-[#16181f]/60 p-8 text-center">
          <PackageOpen className="mx-auto mb-2 h-8 w-8 text-white/30" />
          <p className="text-sm font-bold text-white/80">No hay productos que coincidan</p>
          <p className="mt-1 text-xs text-white/45">Prueba cambiando el filtro o la búsqueda</p>
          <button
            type="button"
            onClick={clearFilters}
            className="mt-3 inline-flex items-center gap-1 rounded-xl bg-[#ffff00] px-3.5 py-1.5 text-xs font-black text-black active:scale-95 shadow-md shadow-[#ffff00]/20"
          >
            Ver todos los productos
          </button>
        </div>
      ) : (
        <div className="grid gap-2" style={{ gridTemplateColumns: 'repeat(3, minmax(0, 1fr))' }}>
          {visibleItems.map((child, index) => (
            <div key={child?.key || index} className="min-w-0">
              {child}
            </div>
          ))}
        </div>
      )}
    </section>
  )
}

