function ManualCatalogCard({ product, onSelect }) {
  const [isWide, setIsWide] = useState(false)
  const [imgLoaded, setImgLoaded] = useState(false)

  const handleImgLoad = (e) => {
    setImgLoaded(true)
    if (e.target && e.target.naturalWidth && e.target.naturalHeight) {
      if (e.target.naturalWidth / e.target.naturalHeight > 1.2) {
        setIsWide(true)
      }
    }
  }

  const iconSrc = product.icon_url ? `${product.icon_url}?v=${cacheBust}` : ''

  return (
    <button
      onClick={onSelect}
      className="fs-catalog-card-3d group relative flex h-full w-full min-w-0 flex-col overflow-hidden rounded-xl border border-white/10 bg-[#16181f]/90 text-left transition-all duration-300 active:scale-95 hover:border-[#ffff00]/80 hover:-translate-y-0.5"
    >
      <span className="block relative aspect-[1/1.1] w-full flex-shrink-0 overflow-hidden bg-[#101318]">
        {iconSrc ? (
          <OptimizedImage
            src={iconSrc}
            className={`relative z-10 h-full w-full ${isWide ? 'object-contain p-1.5' : 'object-cover'} transition-transform duration-500 ease-out group-hover:scale-105 opacity-100`}
            alt={product.name}
            onLoad={handleImgLoad}
          />
        ) : (
          <span className="block flex h-full w-full items-center justify-center bg-white/5"><CategoryIcon category={product.category} className="h-8 w-8 text-white/40" /></span>
        )}
        <span className="pointer-events-none absolute inset-x-0 bottom-0 h-8 bg-gradient-to-t from-[#16181f] to-transparent z-10" />
        <span className="block absolute left-1.5 top-1.5 z-20 max-w-[calc(100%-12px)] truncate rounded-full bg-black/90 border border-[#ffff00]/40 px-1.5 py-0.5 text-[8px] font-black uppercase tracking-wider text-[#ffff00] shadow-md">
          {deliveryTypeLabel(product.delivery_type, product.category)}
        </span>
      </span>
      <span className="block flex-1 p-1.5">
        <span className="block line-clamp-1 truncate text-[11px] font-bold leading-tight text-white group-hover:text-[#ffff00] transition-colors">{product.name}</span>
        <span className="block mt-0.5 truncate text-[10px] font-black text-[#ffff00]">{manualProductPriceRange(product)}</span>
      </span>
    </button>
  )
}

function GameCard({ game, onSelect }) {
  const [imgError, setImgError] = useState(false)
  const [imgLoaded, setImgLoaded] = useState(false)
  const [isWide, setIsWide] = useState(false)

  const rawImage = game.image_url || game.icon_url || ''
  
  // Prefer official Steam vertical cover (library_600x900.jpg) when header.jpg is present
  const preferredImage = useMemo(() => {
    if (!rawImage) return ''
    const base = rawImage.startsWith('/api/') ? `${rawImage}?v=${cacheBust}` : rawImage
    if (base.includes('steamstatic.com/steam/apps/') && base.includes('/header.jpg')) {
      return base.replace('/header.jpg', '/library_600x900.jpg')
    }
    return base
  }, [rawImage])

  const [currentSrc, setCurrentSrc] = useState(preferredImage)
  const [triedFallback, setTriedFallback] = useState(false)

  useEffect(() => {
    setCurrentSrc(preferredImage)
    setImgError(false)
    setImgLoaded(false)
    setTriedFallback(false)
    setIsWide(false)
  }, [preferredImage])

  const handleImgError = () => {
    if (!triedFallback && currentSrc.includes('/library_600x900.jpg')) {
      setTriedFallback(true)
      const orig = rawImage.startsWith('/api/') ? `${rawImage}?v=${cacheBust}` : rawImage
      setCurrentSrc(orig)
      setIsWide(true)
    } else {
      setImgError(true)
    }
  }

  const handleImgLoad = (e) => {
    setImgLoaded(true)
    if (e.target && e.target.naturalWidth && e.target.naturalHeight) {
      if (e.target.naturalWidth / e.target.naturalHeight > 1.2) {
        setIsWide(true)
      }
    }
  }

  const showImage = !!currentSrc && !imgError
  const TypeIcon = game.catalogType === 'card' ? Gift : game.catalogType === 'game-cdkey' ? KeyRound : game.catalogType === 'game-console' ? Gamepad2 : Smartphone
  const badgeLabel = game.provider_type === 'topup' ? 'Top-Up' : game.provider_type === 'giftcard' ? 'Gift Card' : game.provider_type === 'gamekey' ? 'CD-Key' : (game.catalogType === 'card' ? 'Gift Card' : game.catalogType === 'direct-topup' ? 'Top-Up' : game.catalogType === 'game-cdkey' ? 'CD-Key' : 'Juego')

  const handlePointerPrefetch = () => {
    if (game?.provider_type && game?.category_id) {
      api.fzrCatalogOffers(game.provider_type, game.category_id).catch(() => {})
    } else if (game?.name) {
      api.publicRegions(game.name).catch(() => {})
      api.regions(game.name).catch(() => {})
    }
  }

  return (
    <button
      onClick={onSelect}
      onMouseEnter={handlePointerPrefetch}
      className="fs-catalog-card-3d group relative flex h-full w-full min-w-0 flex-col overflow-hidden rounded-xl border border-white/10 bg-[#16181f]/90 text-left transition-all duration-300 active:scale-95 hover:border-[#ffff00]/80 hover:-translate-y-0.5"
    >
      <span className="block relative aspect-[1/1.1] w-full flex-shrink-0 overflow-hidden bg-[#101318]">
        {showImage && (
          <OptimizedImage
            src={currentSrc}
            alt={game.title || game.name}
            className={`relative z-10 h-full w-full ${isWide ? 'object-contain p-1.5' : 'object-cover'} transition-transform duration-500 ease-out group-hover:scale-105 opacity-100`}
            onError={handleImgError}
            onLoad={handleImgLoad}
          />
        )}
        {!showImage && (
          <span className="block absolute inset-0 flex items-center justify-center bg-white/5">
            <TypeIcon className="h-8 w-8 text-white/40" aria-hidden="true" />
          </span>
        )}
        <span className="pointer-events-none absolute inset-x-0 bottom-0 h-8 bg-gradient-to-t from-[#16181f] to-transparent z-10" />
        <span className="block absolute left-1.5 top-1.5 z-20 max-w-[calc(100%-12px)] truncate rounded-full bg-black/90 border border-[#ffff00]/40 px-1.5 py-0.5 text-[8px] font-black uppercase tracking-wider text-[#ffff00] shadow-md">
          {badgeLabel}
        </span>
      </span>
      <span className="block flex-1 p-1.5">
        <span className="block line-clamp-2 text-[11px] font-bold leading-tight text-white group-hover:text-[#ffff00] transition-colors">
          {game.title || game.name}
        </span>
      </span>
    </button>
  )
}

function RegionsScreen({ game, gameData, me, onSelectRegion, onCountKnown }) {
  const [regions, setRegions] = useState([])
  const [loading, setLoading] = useState(true)
  const [err, setErr] = useState(null)

  function markReviewed(order, review) {
    setOrders(items => items.map(item => item.type === order.type && item.id === order.id ? { ...item, review } : item))
  }

  useEffect(() => {
    let cancelled = false;
    (me?.is_guest ? api.publicRegions(game) : api.regions(game)).then((r) => {
      if (cancelled) return
      const arr = Array.isArray(r) ? r : []
      const uniqueRegions = [...new Map(arr.filter(Boolean).map(item => [item.raw_name || item.name || item, item])).values()]
      setRegions(uniqueRegions)
      setLoading(false)
      // Background prefetch products for visible regions so clicking is instant
      setTimeout(() => {
        uniqueRegions.slice(0, 4).forEach((reg) => {
          const regName = reg.raw_name || reg.name || reg
          if (regName) {
            (me?.is_guest ? api.publicProducts(game, regName) : api.products(game, regName)).catch(() => {})
          }
        })
      }, 100)
    }).catch((e) => {
      if (cancelled) return
      setErr(e.message)
      setLoading(false)
    })
    return () => { cancelled = true }
  }, [game, me?.is_guest])

  useEffect(() => {
    if (loading || err) return
    if (typeof onCountKnown === 'function') onCountKnown(regions.length)
  }, [regions, loading, err, onCountKnown])

  useEffect(() => {
    if (loading || err || regions.length !== 1) return
    const onlyRegion = regions[0]?.raw_name || regions[0]?.name || regions[0]
    if (onlyRegion === 'Global') {
      onSelectRegion('Global')
    }
  }, [regions, loading, err, onSelectRegion])

  if (loading) {
    const iconUrl = gameData?.icon_url
    return (
      <div className="px-2.5 py-4 md:p-6">
        <div className="flex items-center gap-3 mb-4">
          {iconUrl ? (
            <OptimizedImage src={`${iconUrl}?v=${cacheBust}`} alt="" className="w-14 h-14 rounded-xl object-cover" eager />
          ) : (
            <div className="w-14 h-14 rounded-xl bg-card flex items-center justify-center text-2xl">
              <Gamepad2 className="h-7 w-7 text-white/60" aria-hidden="true" />
            </div>
          )}
          <div>
            <h2 className="text-xl font-bold">{gameData?.title || game}</h2>
            <p className="text-sm text-white/50 inline-flex items-center gap-1"><Globe2 className="h-4 w-4" aria-hidden="true" />Selecciona tu región</p>
          </div>
        </div>
        <div className="grid grid-cols-3 gap-2">
          {[1, 2, 3, 4, 5, 6].map(i => (
            <div key={i} className="h-16 rounded-xl border border-white/5 bg-card/60 animate-pulse" />
          ))}
        </div>
      </div>
    )
  }
  if (err) return <ErrorView msg={err} />

  const iconUrl = gameData?.icon_url
  // Local cacheBust removed

  return (
    <div className="px-2.5 py-4 md:p-6">
      <div className="flex items-center gap-3 mb-4">
        {iconUrl ? (
          <OptimizedImage src={`${iconUrl}?v=${cacheBust}`} alt="" className="w-14 h-14 rounded-xl object-cover" eager />
        ) : (
          <div className="w-14 h-14 rounded-xl bg-card flex items-center justify-center text-2xl">
            <Gamepad2 className="h-7 w-7 text-white/60" aria-hidden="true" />
          </div>
        )}
        <div>
          <h2 className="text-xl font-bold">{gameData?.title || game}</h2>
          <p className="text-sm text-white/50 inline-flex items-center gap-1"><Globe2 className="h-4 w-4" aria-hidden="true" />Selecciona tu región</p>
        </div>
      </div>
      <div className="grid grid-cols-3 gap-2">
        {regions.map((r) => {
          const prefetchProducts = () => {
            (me?.is_guest ? api.publicProducts(game, r.raw_name) : api.products(game, r.raw_name)).catch(() => {})
          }
          return (
            <button
              key={r.raw_name}
              onClick={() => onSelectRegion(r.raw_name)}
              onMouseEnter={prefetchProducts}
              onTouchStart={prefetchProducts}
              className="card flex min-h-[82px] flex-col items-center justify-center p-2 text-center transition active:scale-95 hover:border-accent/50"
            >
              <span className="line-clamp-2 break-words text-xs font-black leading-tight">{r.name}</span>
              <span className="mt-1 text-[10px] text-white/45">{r.count} productos</span>
            </button>
          )
        })}
      </div>
    </div>
  )
}


function getDenominationLabel(productName = '', gameTitle = '') {
  const original = stripEmoji(String(productName || '')).replace(/\s+/g, ' ').trim()
  let text = original
  const title = stripEmoji(String(gameTitle || '')).replace(/\s+/g, ' ').trim()
  if (title) {
    const escaped = title.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    text = text.replace(new RegExp(`^${escaped}\\s+`, 'i'), '').trim()
  }
  text = text
    .replace(/^Genshin Impact\s+/ig, '')
    .replace(/^Blood Strike\s+/ig, '')
    .replace(/^Arena Breakou?t\s+/ig, '')
    .replace(/\(\s*O\s*\)/ig, '')
    .replace(/^Top\s*-?\s*Up\s+/ig, '')
    .replace(/\s+/g, ' ')
    .trim()
  if (/^\d/.test(original) && !/^\d/.test(text)) return original
  return text || original
}

function formatRechargeDetails(details = []) {
  return (Array.isArray(details) ? details : []).filter(item => item && item.value).map(item => ({
    label: item.kind === 'id' ? 'ID de cuenta' : item.kind === 'region' ? 'Región / servidor' : item.label,
    value: item.value,
  }))
}


function getGenshinAmountKey(name = '') {
  const text = normalizeCatalogText(name).replace(/,/g, '')
  const pair = text.match(/(\d+)\s*\+\s*(\d+)/)
  if (pair) return `${Number(pair[1])}+${Number(pair[2])}`
  const single = text.match(/(^|\s)(\d+)(?=\s+(genesis\s+)?crystals?\b|\s+chronal\s+nexus\b)/)
  if (single) return `${Number(single[2])}+0`
  return text
}

function getGenshinDisplayName(product, groupId) {
  const raw = String(product?.name || '').replace(/\s+/g, ' ').trim()
  const key = getGenshinAmountKey(raw)
  const pair = key.match(/^(\d+)\+(\d+)$/)
  if (!pair) return raw
  const base = Number(pair[1])
  const bonus = Number(pair[2])
  const amount = bonus > 0 ? `${base} + ${bonus}` : `${base}`
  if (groupId === 'chronal') return `${amount} Chronal Nexus`
  if (groupId === 'genesis') return `${amount} Genesis Crystals`
  return raw
}

function getGenshinPreferenceScore(product, groupId) {
  const name = normalizeCatalogText(product?.name || '')
  let score = 0
  if (groupId === 'genesis' && /genesis crystals/.test(name)) score += 50
  if (groupId === 'chronal' && /chronal nexus/.test(name)) score += 50
  if (/\bcrystals\b/.test(name)) score += 10
  if (/\bcrystal\b/.test(name)) score += 5
  if (/all pack|blessing|welkin|pass|bundle|monthly|quarterly/.test(name)) score -= 100
  return score
}

function dedupeGenshinGroup(items, groupId) {
  const byAmount = new Map()
  items.forEach((product) => {
    const key = getGenshinAmountKey(product.name)
    const candidate = { ...product, displayName: getGenshinDisplayName(product, groupId) }
    const current = byAmount.get(key)
    if (!current) {
      byAmount.set(key, candidate)
      return
    }
    const candidateScore = getGenshinPreferenceScore(candidate, groupId)
    const currentScore = getGenshinPreferenceScore(current, groupId)
    if (candidateScore > currentScore || (candidateScore === currentScore && Number(candidate.price || 0) < Number(current.price || 0))) {
      byAmount.set(key, candidate)
    }
  })
  return sortProductsByValue([...byAmount.values()])
}

function getProductDisplayGroups(products = [], gameTitle = '') {
  const title = normalizeCatalogText(gameTitle)
  if (!/genshin/.test(title)) return [{ id: 'all', title: null, items: products }]

  const groups = [
    { id: 'genesis', title: 'Genesis Crystals', items: [] },
    { id: 'chronal', title: 'Chronal Nexus', items: [] },
    { id: 'passes', title: 'Pases y paquetes', items: [] },
  ]
  products.forEach((product) => {
    const name = normalizeCatalogText(product.name)
    if (/all pack|blessing|welkin|pass|bundle|monthly|quarterly/.test(name)) groups[2].items.push(product)
    else if (/chronal nexus/.test(name)) groups[1].items.push(product)
    else if (/genesis crystals?|\bcrystals?\b/.test(name)) groups[0].items.push(product)
    else groups[2].items.push(product)
  })
  groups[0].items = dedupeGenshinGroup(groups[0].items, 'genesis')
  groups[1].items = dedupeGenshinGroup(groups[1].items, 'chronal')
  groups[2].items = sortProductsByValue(groups[2].items)
  return groups.filter(group => group.items.length > 0)
}

