function RegisterScreen({ onSuccess, onLoginSuccess, onLogin, onClose }) {
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [password2, setPassword2] = useState('')
  const [termsAccepted, setTermsAccepted] = useState(false)
  const [showTermsModal, setShowTermsModal] = useState(false)
  const [referralCode, setReferralCode] = useState(() => {
    try {
      const p = new URLSearchParams(window.location.search)
      return p.get('ref') || localStorage.getItem('fs_pending_ref') || ''
    } catch {
      return ''
    }
  })
  const [loading, setLoading] = useState(false)
  const [err, setErr] = useState(null)
  const [done, setDone] = useState(false)

  const handleReferralChange = (val) => {
    const clean = val.replace(/[^0-9]/g, '').slice(0, 7)
    setReferralCode(clean)
    try {
      if (clean) localStorage.setItem('fs_pending_ref', clean)
      else localStorage.removeItem('fs_pending_ref')
    } catch {}
  }

  async function handleRegister() {
    if (password !== password2) { setErr('Las contraseñas no coinciden'); return }
    if (password.length < 8) { setErr('La contraseña debe tener al menos 8 caracteres'); return }
    if (!termsAccepted) { setErr('Debes aceptar los Términos y Condiciones para crear tu cuenta'); return }
    setLoading(true); setErr(null)
    try {
      await api.register(email, password, name, referralCode.trim() || null)
      setDone(true)
    } catch (e) { setErr(e.message); setLoading(false) }
  }

  if (done) return (
    <AuthWrapper title={<span className="inline-flex items-center gap-2"><Mail className="h-5 w-5 text-accent" />Revisa tu email</span>}>
      <div className="card p-5 text-center bg-white/5 border border-white/10 rounded-2xl">
        <Inbox className="mx-auto mb-3 h-10 w-10 text-accent" aria-hidden="true" />
        <p className="text-sm text-white/80 mb-4">
          Enviamos un código de verificación a <b className="text-white">{email}</b>
        </p>
        <button
          onClick={() => onSuccess(email)}
          className="w-full py-3.5 rounded-xl font-bold text-sm bg-gradient-to-r from-accent to-accent2 text-white shadow-lg shadow-accent/25 active:scale-[0.98] transition"
        >
          Verificar email
        </button>
      </div>
      <button onClick={onLogin} className="text-accent text-xs mt-4 block mx-auto hover:underline">
        Volver a iniciar sesión
      </button>
      {onClose && (
        <button type="button" onClick={onClose} className="mt-2 block mx-auto text-xs text-white/45 hover:text-white/80 transition">
          Continuar como invitado
        </button>
      )}
    </AuthWrapper>
  )

  return (
    <AuthWrapper
      activeTab="register"
      onTabChange={(tab) => { if (tab === 'login') onLogin() }}
      title="Crear cuenta"
    >
      {showTermsModal && <TermsSummaryModal onClose={() => setShowTermsModal(false)} />}
      {err && (
        <div className="mb-4 rounded-xl border border-red-500/25 bg-red-500/10 p-3 text-center text-xs text-red-200 flex items-center justify-center gap-2">
          <AlertTriangle className="h-4 w-4 flex-shrink-0 text-red-400" />
          <span>{err}</span>
        </div>
      )}

      <div className="space-y-1.5 mb-2">
        <GoogleSignInButton
          text="signup_with"
          onSuccess={(me) => {
            if (onLoginSuccess) onLoginSuccess(me)
            else if (onSuccess) onSuccess(me)
          }}
          onError={setErr}
        />

        <TelegramLoginButton
          text="Registrarse con Telegram"
          onSuccess={(me) => {
            if (onLoginSuccess) onLoginSuccess(me)
            else if (onSuccess) onSuccess(me)
          }}
          onError={setErr}
        />

        <div className="relative flex py-2 items-center my-1.5 max-w-[290px] mx-auto">
          <div className="flex-grow border-t border-white/10" />
          <span className="flex-shrink mx-3 text-[10px] text-white/35 uppercase tracking-widest font-semibold">o con email</span>
          <div className="flex-grow border-t border-white/10" />
        </div>
      </div>

      <form onSubmit={(e) => { e.preventDefault(); handleRegister(); }} className="space-y-3">
        <div className="relative group">
          <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-white/30 group-focus-within:text-accent transition-colors pointer-events-none">
            <User className="h-4 w-4" />
          </div>
          <input
            type="text"
            placeholder="Tu nombre completo o apodo"
            value={name}
            onChange={e => setName(e.target.value)}
            autoComplete="name"
            className="w-full bg-[#141b2d]/90 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-sm text-white placeholder-white/30 outline-none transition-all focus:border-accent focus:ring-1 focus:ring-accent/40 focus:bg-[#182136]"
            required
          />
        </div>

        <div className="relative group">
          <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-white/30 group-focus-within:text-accent transition-colors pointer-events-none">
            <Mail className="h-4 w-4" />
          </div>
          <input
            type="email"
            placeholder="Correo electrónico"
            value={email}
            onChange={e => setEmail(e.target.value)}
            autoComplete="email"
            className="w-full bg-[#141b2d]/90 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-sm text-white placeholder-white/30 outline-none transition-all focus:border-accent focus:ring-1 focus:ring-accent/40 focus:bg-[#182136]"
            required
          />
        </div>

        <PasswordInput
          placeholder="Contraseña (mínimo 8 caracteres)"
          value={password}
          onChange={e => setPassword(e.target.value)}
          autoComplete="new-password"
        />

        <PasswordInput
          placeholder="Repetir contraseña"
          value={password2}
          onChange={e => setPassword2(e.target.value)}
          autoComplete="new-password"
        />

        {/* Código de referido / invitación */}
        <div className="relative group">
          <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-white/30 group-focus-within:text-accent transition-colors pointer-events-none">
            <Gift className="h-4 w-4" />
          </div>
          <input
            type="text"
            inputMode="numeric"
            pattern="[0-9]*"
            maxLength={7}
            placeholder="Código de invitación (opcional)"
            value={referralCode}
            onChange={e => handleReferralChange(e.target.value)}
            className="w-full bg-[#141b2d]/90 border border-white/10 rounded-xl pl-10 pr-10 py-3 text-sm text-white placeholder:font-sans placeholder:tracking-normal placeholder-white/30 outline-none transition-all focus:border-accent focus:ring-1 focus:ring-accent/40 focus:bg-[#182136] font-mono tracking-wider"
          />
          {referralCode && referralCode.length === 7 && (
            <div className="absolute right-3.5 top-1/2 -translate-y-1/2 text-emerald-400">
              <Check className="h-4 w-4" />
            </div>
          )}
        </div>

        {/* Aceptación de términos y condiciones para registro */}
        <div className="rounded-xl border border-white/10 bg-black/40 p-2.5">
          <label className="flex items-start gap-2.5 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={termsAccepted}
              onChange={(e) => setTermsAccepted(e.target.checked)}
              className="mt-0.5 h-4 w-4 rounded border-white/20 bg-black/60 text-accent focus:ring-accent accent-accent flex-shrink-0 cursor-pointer"
            />
            <span className="text-[11px] text-white/80 leading-snug">
              He leído y acepto los{' '}
              <button
                type="button"
                onClick={(e) => { e.preventDefault(); e.stopPropagation(); setShowTermsModal(true); }}
                className="text-accent underline font-semibold hover:text-accent/80"
              >
                Términos y Condiciones
              </button>{' '}
              generales del servicio y la política de compras.
            </span>
          </label>
        </div>

        <button
          type="submit"
          disabled={loading || !email || !password || !password2 || !termsAccepted}
          className="w-full py-3.5 rounded-xl font-bold text-sm bg-gradient-to-r from-accent to-accent2 text-white shadow-lg shadow-accent/25 active:scale-[0.98] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
        >
          {loading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              <span>Creando cuenta...</span>
            </>
          ) : (
            <>
              <Edit3 className="h-4 w-4" />
              <span>Crear cuenta gratis</span>
            </>
          )}
        </button>
      </form>

      {onClose && (
        <button
          type="button"
          onClick={onClose}
          className="mt-4 block mx-auto text-xs text-white/45 hover:text-white/80 transition"
        >
          Continuar como invitado
        </button>
      )}
    </AuthWrapper>
  )
}

