function VerifyScreen({ onSuccess, defaultEmail = '' }) {
  const [email, setEmail] = useState(defaultEmail)
  const [code, setCode] = useState('')
  const [loading, setLoading] = useState(false)
  const [err, setErr] = useState(null)
  const [resending, setResending] = useState(false)
  const [resendCooldown, setResendCooldown] = useState(0)
  const [resendMessage, setResendMessage] = useState('')

  useEffect(() => {
    if (resendCooldown <= 0) return undefined
    const timer = window.setTimeout(() => setResendCooldown((seconds) => seconds - 1), 1000)
    return () => window.clearTimeout(timer)
  }, [resendCooldown])

  async function handleVerify(e) {
    e?.preventDefault()
    setLoading(true); setErr(null)
    try {
      await api.verifyEmail(email, code)
      onSuccess()
    } catch (e) { setErr(e.message); setLoading(false) }
  }

  async function handleResend() {
    if (!email || resending || resendCooldown > 0) return
    setResending(true)
    setResendMessage('')
    setErr(null)
    try {
      const response = await api.resendEmailVerification(email)
      setResendMessage(response?.message || 'Te enviamos un código nuevo.')
      setResendCooldown(60)
    } catch (error) {
      setErr(error.message || 'No se pudo reenviar el código.')
    } finally {
      setResending(false)
    }
  }

  return (
    <AuthWrapper title="Verificar email" subtitle="Ingresa el código de 6 dígitos que enviamos a tu correo">
      {err && (
        <div className="mb-4 rounded-xl border border-red-500/25 bg-red-500/10 p-3 text-center text-xs text-red-200 flex items-center justify-center gap-2">
          <AlertTriangle className="h-4 w-4 flex-shrink-0 text-red-400" />
          <span>{err}</span>
        </div>
      )}
      <form onSubmit={handleVerify} className="space-y-3">
        <div className="relative group">
          <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-white/30 group-focus-within:text-accent transition-colors pointer-events-none">
            <Mail className="h-4 w-4" />
          </div>
          <input
            type="email"
            placeholder="Tu correo electrónico"
            value={email}
            onChange={e => setEmail(e.target.value)}
            autoComplete="email"
            className="w-full bg-[#141b2d]/90 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-sm text-white placeholder-white/30 outline-none transition-all focus:border-accent focus:ring-1 focus:ring-accent/40 focus:bg-[#182136]"
            required
          />
        </div>
        <div>
          <input
            type="text"
            placeholder="000000"
            value={code}
            maxLength={6}
            inputMode="numeric"
            autoComplete="one-time-code"
            onChange={e => setCode(e.target.value.replace(/\D/g, ''))}
            className="w-full bg-[#141b2d]/90 border border-white/10 rounded-xl px-4 py-3.5 outline-none transition-all focus:border-accent focus:ring-1 focus:ring-accent/40 focus:bg-[#182136] text-center text-2xl tracking-[0.4em] font-mono text-white placeholder-white/20"
            required
          />
        </div>
        <button
          type="submit"
          disabled={loading || !email || code.length < 6}
          className="w-full py-3.5 rounded-xl font-bold text-sm bg-gradient-to-r from-accent to-accent2 text-white shadow-lg shadow-accent/25 active:scale-[0.98] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
        >
          {loading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              <span>Verificando...</span>
            </>
          ) : (
            <>
              <Check className="h-4 w-4" />
              <span>Verificar y continuar</span>
            </>
          )}
        </button>
        <div className="pt-1 text-center">
          <p className="mb-2 text-[11px] text-white/45">¿No recibiste el código?</p>
          <button
            type="button"
            onClick={handleResend}
            disabled={!email || resending || resendCooldown > 0}
            className="text-xs font-bold text-accent transition hover:underline disabled:cursor-not-allowed disabled:opacity-45"
          >
            {resending ? 'Reenviando...' : resendCooldown > 0 ? `Reenviar en ${resendCooldown}s` : 'Reenviar código'}
          </button>
          {resendMessage && <p className="mt-2 text-[11px] leading-relaxed text-emerald-300">{resendMessage}</p>}
        </div>
      </form>
    </AuthWrapper>
  )
}

function ResetScreen({ onSuccess, onLoginSuccess, onClose, defaultEmail = '' }) {
  const [email, setEmail] = useState(() => {
    try {
      const sp = new URLSearchParams(window.location.search)
      return sp.get('email') || defaultEmail || ''
    } catch {
      return defaultEmail || ''
    }
  })
  const [code, setCode] = useState(() => {
    try {
      const sp = new URLSearchParams(window.location.search)
      return sp.get('code') || ''
    } catch {
      return ''
    }
  })
  const [password, setPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const [err, setErr] = useState(null)
  const [done, setDone] = useState(false)
  const [loggedInUser, setLoggedInUser] = useState(null)

  const isSetPasswordMode = (() => {
    try {
      const sp = new URLSearchParams(window.location.search)
      const action = sp.get('action')
      return action === 'set-password' || (!sp.has('reset') && sp.get('action') !== 'reset-password' && !!sp.get('code'))
    } catch {
      return false
    }
  })()

  async function handleReset(e) {
    e?.preventDefault()
    if (password.length < 8) {
      setErr('La contraseña debe tener mínimo 8 caracteres')
      return
    }
    setLoading(true)
    setErr(null)
    try {
      await api.resetPassword(email, code, password)
      try {
        await api.login(email, password)
        const newMe = await api.me()
        if (newMe) {
          setLoggedInUser(newMe)
        }
      } catch (autoLoginErr) {
        console.warn('Auto-login tras crear contraseña omitido:', autoLoginErr)
      }
      setDone(true)
    } catch (e) {
      setErr(e.message)
      setLoading(false)
    }
  }

  if (done) return (
    <AuthWrapper
      title={
        <span className="inline-flex items-center gap-2">
          <CircleCheck className="h-5 w-5 text-emerald-400" />
          {isSetPasswordMode ? 'Contraseña establecida' : 'Contraseña actualizada'}
        </span>
      }
    >
      <div className="card p-5 text-center bg-white/5 border border-white/10 rounded-2xl">
        <LockKeyhole className="mx-auto mb-3 h-10 w-10 text-emerald-400" aria-hidden="true" />
        <p className="text-sm text-white/90 font-medium mb-1.5">
          {loggedInUser
            ? '¡Tu contraseña ha sido guardada y tu sesión está iniciada!'
            : 'Tu contraseña ha sido guardada exitosamente.'}
        </p>
        <p className="text-xs text-white/60 mb-5 leading-relaxed">
          Ahora puedes acceder a Francho Shop desde cualquier dispositivo o navegador con tu correo y tu nueva contraseña.
        </p>
        {loggedInUser && onLoginSuccess ? (
          <button
            onClick={() => {
              if (window.location.search) {
                window.history.replaceState({}, '', '/')
              }
              onLoginSuccess(loggedInUser)
            }}
            className="w-full py-3.5 rounded-xl font-bold text-sm bg-gradient-to-r from-accent to-accent2 text-white shadow-lg shadow-accent/25 active:scale-[0.98] transition"
          >
            Entrar a la tienda
          </button>
        ) : (
          <button
            onClick={() => {
              if (window.location.search) {
                window.history.replaceState({}, '', '/')
              }
              onSuccess?.()
            }}
            className="w-full py-3.5 rounded-xl font-bold text-sm bg-gradient-to-r from-accent to-accent2 text-white shadow-lg shadow-accent/25 active:scale-[0.98] transition"
          >
            Ir al inicio de sesión
          </button>
        )}
      </div>
    </AuthWrapper>
  )

  return (
    <AuthWrapper
      title={isSetPasswordMode ? 'Crear contraseña' : 'Nueva contraseña'}
      subtitle={
        isSetPasswordMode
          ? 'Crea una contraseña segura para entrar directamente sin depender de Google'
          : 'Crea una contraseña segura de mínimo 8 caracteres'
      }
    >
      {err && (
        <div className="mb-4 rounded-xl border border-red-500/25 bg-red-500/10 p-3 text-center text-xs text-red-200 flex items-center justify-center gap-2">
          <AlertTriangle className="h-4 w-4 flex-shrink-0 text-red-400" />
          <span>{err}</span>
        </div>
      )}
      <form onSubmit={handleReset} className="space-y-3">
        <div className="relative group">
          <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-white/30 group-focus-within:text-accent transition-colors pointer-events-none">
            <Mail className="h-4 w-4" />
          </div>
          <input
            type="email"
            placeholder="Correo electrónico"
            value={email}
            onChange={e => setEmail(e.target.value)}
            autoComplete="email"
            className="w-full bg-[#141b2d]/90 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-sm text-white placeholder-white/30 outline-none transition-all focus:border-accent focus:ring-1 focus:ring-accent/40 focus:bg-[#182136]"
            required
          />
        </div>
        <div>
          <label className="block text-[11px] font-semibold text-white/50 mb-1 pl-1">
            Código de verificación (6 dígitos enviado a tu correo):
          </label>
          <input
            type="text"
            placeholder="Código de 6 dígitos"
            value={code}
            maxLength={6}
            inputMode="numeric"
            autoComplete="one-time-code"
            onChange={e => setCode(e.target.value.replace(/\D/g, ''))}
            className="w-full bg-[#141b2d]/90 border border-white/10 rounded-xl px-4 py-3 outline-none transition-all focus:border-accent focus:ring-1 focus:ring-accent/40 focus:bg-[#182136] text-center text-lg tracking-widest font-mono text-white placeholder-white/30"
            required
          />
        </div>
        <PasswordInput
          placeholder="Nueva contraseña (mínimo 8 caracteres)"
          value={password}
          onChange={e => setPassword(e.target.value)}
          autoComplete="new-password"
        />
        <button
          type="submit"
          disabled={loading || !email || code.length < 6 || !password}
          className="w-full py-3.5 rounded-xl font-bold text-sm bg-gradient-to-r from-accent to-accent2 text-white shadow-lg shadow-accent/25 active:scale-[0.98] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
        >
          {loading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              <span>Guardando...</span>
            </>
          ) : (
            <>
              <Check className="h-4 w-4" />
              <span>{isSetPasswordMode ? 'Establecer contraseña' : 'Guardar contraseña'}</span>
            </>
          )}
        </button>
      </form>
    </AuthWrapper>
  )
}


function ErrorView({ msg, onRetry, onLogin }) {
  const isInTelegram = !!(tg && tg.platform && tg.platform !== 'unknown')
  const msgStr = String(msg || '')
  const isAuthError = msgStr.includes('initData') || msgStr.includes('token') || msgStr.includes('Sesión') || msgStr.includes('401')

  return (
    <div className="p-8 text-center max-w-sm mx-auto animate-in fade-in">
      <BigIcon icon={AlertTriangle} className="mx-auto mb-4 text-yellow-400" />
      <p className="text-red-400 font-semibold whitespace-pre-line text-sm">
        {isAuthError ? 'Tu sesión ha expirado o necesitas iniciar sesión.' : msg}
      </p>
      {isAuthError ? (
        <div className="mt-5 space-y-2">
          <button
            type="button"
            onClick={() => {
              if (onLogin) onLogin()
              else if (typeof window !== 'undefined') window.location.href = '/login'
            }}
            className="w-full py-3 rounded-xl bg-accent text-black font-black text-xs active:scale-95 transition shadow-lg cursor-pointer"
          >
            Iniciar Sesión
          </button>
          <button
            type="button"
            onClick={() => {
              if (typeof window !== 'undefined') window.location.href = '/'
            }}
            className="w-full py-2.5 rounded-xl bg-white/5 hover:bg-white/10 text-white/70 font-bold text-xs active:scale-95 transition border border-white/10 cursor-pointer"
          >
            Ir a la Tienda
          </button>
        </div>
      ) : isInTelegram ? (
        <div className="mt-4">
          <p className="text-white/50 text-xs mb-3">
            Cierra esta ventana y usa el botón "Shop" al lado del campo de texto del bot.
          </p>
          <button onClick={() => window.Telegram?.WebApp?.close?.()} className="card px-6 py-3 text-accent font-semibold active:scale-95">
            ✕ Cerrar
          </button>
        </div>
      ) : (
        <button onClick={onRetry || (() => location.reload())} className="card px-6 py-3 mt-6 text-accent font-semibold active:scale-95">
          <span className="inline-flex items-center justify-center gap-2"><LabelIcon icon={RefreshCcw} />Reintentar</span>
        </button>
      )}
    </div>
  )
}

