function PaymentAssetIcon({ symbol = '', network = '', className = 'h-6 w-6' }) {
  const source = symbol ? PAYMENT_COIN_ICONS[String(symbol).toUpperCase()] : PAYMENT_NETWORK_ICONS[String(network).toLowerCase()]
  const fallback = symbol || String(network).slice(0, 2).toUpperCase() || '$'
  const [loaded, setLoaded] = useState(false)
  const [failed, setFailed] = useState(false)

  useEffect(() => {
    setLoaded(false)
    setFailed(false)
  }, [source])

  return (
    <span className={`${className} relative grid shrink-0 place-items-center overflow-hidden rounded-full bg-white/10 text-[9px] font-black text-white/75`}>
      <span aria-hidden="true" className={loaded ? 'opacity-0' : ''}>{fallback.slice(0, 3)}</span>
      {source && !failed && (
        <img
          src={source}
          alt=""
          className="absolute inset-0 h-full w-full object-contain"
          onLoad={() => setLoaded(true)}
          onError={() => {
            setLoaded(false)
            setFailed(true)
          }}
        />
      )}
    </span>
  )
}

function TopUpModal({ onClose, onPaid, me, initialAmount = '25' }) {
  const [amount, setAmount] = useState(String(initialAmount || '25'))
  const [showTierModal, setShowTierModal] = useState(false)
  const [invoice, setInvoice] = useState(null)
  const [loading, setLoading] = useState(false)
  const [checking, setChecking] = useState(false)
  const [err, setErr] = useState(null)
  const [status, setStatus] = useState(null)
  const [paymentOptions, setPaymentOptions] = useState([])
  const [optionsLoading, setOptionsLoading] = useState(true)
  const [optionsError, setOptionsError] = useState(null)
  const [payCurrency, setPayCurrency] = useState('')
  const [payNetwork, setPayNetwork] = useState('')
  const [paymentSelector, setPaymentSelector] = useState(null)
  const [copied, setCopied] = useState(false)
  const [secondsLeft, setSecondsLeft] = useState(null)
  const selectedAmount = Number(String(amount).replace(',', '.')) || 0
  const payLabel = selectedAmount > 0 ? `Recargar ${selectedAmount.toFixed(2)} USDT` : 'Recargar'

  const currentTier = useMemo(() => getDepositTierDetails(selectedAmount), [selectedAmount])
  const selectedCurrencyOption = useMemo(
    () => paymentOptions.find(item => item.symbol === payCurrency) || null,
    [paymentOptions, payCurrency]
  )
  const availableNetworks = selectedCurrencyOption?.networks || []

  const loadPaymentOptions = async () => {
    setOptionsLoading(true)
    setOptionsError(null)
    try {
      const res = await api.depositPaymentOptions()
      const currencies = Array.isArray(res?.currencies) ? res.currencies : []
      if (!currencies.length) throw new Error('No hay monedas habilitadas para recibir pagos ahora mismo')
      setPaymentOptions(currencies)
      const firstCurrency = currencies.find(item => item.symbol === 'USDT') || currencies[0]
      setPayCurrency(current => currencies.some(item => item.symbol === current) ? current : firstCurrency.symbol)
    } catch (e) {
      setPaymentOptions([])
      setOptionsError(e.message || 'No se pudieron cargar las opciones de pago')
    } finally {
      setOptionsLoading(false)
    }
  }

  useEffect(() => { loadPaymentOptions() }, [])

  useEffect(() => {
    if (!availableNetworks.length) {
      setPayNetwork('')
      return
    }
    const preferred = availableNetworks.find(item => /^(bsc|bep20|binance smart chain)$/i.test(item.network) || /bep20|binance smart chain/i.test(item.name))
    setPayNetwork(current => availableNetworks.some(item => item.network === current) ? current : (preferred || availableNetworks[0]).network)
  }, [payCurrency, availableNetworks.length])

  useEffect(() => {
    if (!invoice?.expired_at) { setSecondsLeft(null); return undefined }
    const update = () => setSecondsLeft(Math.max(0, Math.floor(Number(invoice.expired_at) - Date.now() / 1000)))
    update()
    const timer = window.setInterval(update, 1000)
    return () => window.clearInterval(timer)
  }, [invoice?.expired_at])

  async function createInvoice(value = amount) {
    const numeric = Number(String(value).replace(',', '.'))
    if (!numeric || numeric <= 0) { setErr('Escribe un monto válido'); return }
    if (!payCurrency || !payNetwork) {
      setErr('Selecciona una moneda y una red antes de continuar')
      return
    }
    setLoading(true); setErr(null); setStatus(null)
    try {
      const inv = await api.createWhiteLabelDeposit(numeric, payCurrency, payNetwork)
      setInvoice(inv)
    } catch (e) { setErr(e.message) }
    setLoading(false)
  }

  async function checkPayment(silent = false) {
    if (!invoice?.track_id) return
    if (!silent) { setChecking(true); setErr(null) }
    try {
      const res = await api.checkDeposit(invoice.track_id)
      const nextStatus = String(res.status || '').toLowerCase()
      setStatus(nextStatus)
      if (nextStatus === 'paid') onPaid?.(res.balance)
    } catch (e) { if (!silent) setErr(e.message) }
    if (!silent) setChecking(false)
  }

  useEffect(() => {
    if (!invoice?.track_id || status === 'paid' || secondsLeft === 0) return undefined
    const timer = window.setInterval(() => checkPayment(true), 12000)
    return () => window.clearInterval(timer)
  }, [invoice?.track_id, status, secondsLeft])

  async function copyPaymentAddress() {
    if (!invoice?.address) return
    try {
      await navigator.clipboard.writeText(invoice.address)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1600)
    } catch {
      setErr('No se pudo copiar la dirección. Mantén pulsado para copiarla manualmente.')
    }
  }

  const formatTimeLeft = (seconds) => {
    if (seconds === null) return ''
    const minutes = Math.floor(seconds / 60)
    return `${minutes}:${String(seconds % 60).padStart(2, '0')}`
  }

  return (
    <>
      <div className="fixed inset-0 z-[999999] flex items-end sm:items-center justify-center bg-black/85 backdrop-blur-sm p-0 sm:p-4 text-left" onClick={(e) => e.target === e.currentTarget && onClose()}>
        <div className="w-full max-w-md rounded-t-3xl sm:rounded-3xl bg-bg p-5 border border-white/10 shadow-2xl space-y-4 animate-slide-up sm:animate-scale-in">
          {/* Encabezado */}
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-2.5 min-w-0">
              <div className="w-9 h-9 rounded-xl bg-accent/15 border border-accent/30 flex items-center justify-center text-accent flex-shrink-0">
                <WalletCards className="h-5 w-5" />
              </div>
              <div className="min-w-0">
                <h3 className="text-base sm:text-lg font-black text-white leading-tight truncate">
                  Recargar saldo USDT
                </h3>
                <p className="text-[11px] text-white/50 leading-tight">
                  Elige moneda y red, sin salir de Francho Shop
                </p>
              </div>
            </div>
            <button onClick={onClose} className="rounded-full bg-white/5 p-1.5 text-white/50 hover:text-white hover:bg-white/10 transition-colors flex-shrink-0">
              <X className="h-4 w-4" />
            </button>
          </div>

          {!invoice ? (
            <>
              {/* Contenedor de selección de monto para el tour de recarga */}
              <div data-tour="topup-amount-chips" className="space-y-3 rounded-2xl p-1 -m-1">
                {/* Chips rápidos de monto */}
                <div>
                  <div className="flex items-center justify-between mb-1.5">
                    <label className="text-[11px] font-bold text-white/60 uppercase tracking-wider">
                      Monto rápido:
                    </label>
                    <button
                      type="button"
                      onClick={() => setShowTierModal(true)}
                      className="text-[11px] font-semibold text-accent hover:underline flex items-center gap-1"
                    >
                      <Sparkles className="h-3 w-3" />
                      <span>Ver descuentos</span>
                    </button>
                  </div>
                  <div className="grid grid-cols-4 gap-2">
                    {[10, 25, 50, 100].map((presetVal) => {
                      const isSelected = selectedAmount === presetVal
                      return (
                        <button
                          key={presetVal}
                          type="button"
                          onClick={() => {
                            setAmount(String(presetVal))
                            setErr(null)
                          }}
                          className={`py-2 px-1 rounded-xl border text-center font-bold text-xs sm:text-sm transition-all active:scale-95 ${
                            isSelected
                              ? 'border-accent bg-accent/20 text-accent ring-1 ring-accent/40 shadow-sm'
                              : 'border-white/10 bg-card hover:border-white/20 text-white/80'
                          }`}
                        >
                          ${presetVal}
                        </button>
                      )
                    })}
                  </div>
                </div>

                {/* Input personalizado */}
                <div className="relative">
                  <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-white/40 font-bold text-base">$</span>
                  <input
                    value={amount}
                    onChange={(e) => {
                      setAmount(e.target.value)
                      setErr(null)
                    }}
                    inputMode="decimal"
                    className="w-full rounded-2xl border border-white/10 bg-card pl-8 pr-16 py-3 text-base sm:text-lg font-black text-white outline-none focus:border-accent transition-colors"
                    placeholder="25"
                  />
                  <span className="absolute right-3.5 top-1/2 -translate-y-1/2 text-xs font-bold text-white/40 uppercase">
                    USDT
                  </span>
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <button type="button" onClick={() => setPaymentSelector('currency')} disabled={optionsLoading || !!optionsError} className="relative flex min-h-14 min-w-0 items-center gap-2 overflow-hidden rounded-xl border border-emerald-300/35 bg-gradient-to-b from-emerald-200/15 to-emerald-900/20 px-2.5 text-left text-white shadow-[inset_0_1px_1px_rgba(255,255,255,.2),0_3px_0_#057544,0_8px_16px_rgba(0,194,111,.16)] transition active:translate-y-[2px] disabled:opacity-50">
                    <span aria-hidden="true" className="absolute inset-x-2 top-1 h-2 rounded-full bg-white/15 blur-[1px]" />
                    <PaymentAssetIcon symbol={payCurrency} className="relative h-7 w-7" />
                    <span className="relative min-w-0"><span className="block text-[9px] font-bold uppercase text-white/45">Moneda</span><span className="block truncate text-xs font-black">{payCurrency || 'Cargando'}</span></span>
                    <ChevronDown className="relative ml-auto h-4 w-4 shrink-0 text-emerald-200" />
                  </button>
                  <button type="button" onClick={() => setPaymentSelector('network')} disabled={optionsLoading || !!optionsError || !payCurrency} className="relative flex min-h-14 min-w-0 items-center gap-2 overflow-hidden rounded-xl border border-cyan-300/35 bg-gradient-to-b from-cyan-200/15 to-cyan-900/20 px-2.5 text-left text-white shadow-[inset_0_1px_1px_rgba(255,255,255,.2),0_3px_0_#0c5262,0_8px_16px_rgba(34,211,238,.16)] transition active:translate-y-[2px] disabled:opacity-50">
                    <span aria-hidden="true" className="absolute inset-x-2 top-1 h-2 rounded-full bg-white/15 blur-[1px]" />
                    <PaymentAssetIcon network={payNetwork} className="relative h-7 w-7" />
                    <span className="relative min-w-0"><span className="block text-[9px] font-bold uppercase text-white/45">Red</span><span className="block truncate text-xs font-black">{payNetwork || 'Seleccionar'}</span></span>
                    <ChevronDown className="relative ml-auto h-4 w-4 shrink-0 text-cyan-200" />
                  </button>
                </div>
                {optionsLoading && <p className="flex items-center gap-1.5 text-[11px] text-white/45"><Loader2 className="h-3.5 w-3.5 animate-spin" />Cargando monedas y redes disponibles…</p>}
                {optionsError && (
                  <div className="flex items-center justify-between gap-3 rounded-xl border border-amber-400/25 bg-amber-400/10 p-2.5 text-xs text-amber-100">
                    <span>{optionsError}</span>
                    <button type="button" onClick={loadPaymentOptions} className="shrink-0 font-bold text-amber-300 underline">Reintentar</button>
                  </div>
                )}
              </div>

              {/* Píldora de 1 sola línea con el Nivel alcanzado */}
              <div className="flex items-center justify-between rounded-xl bg-white/5 border border-white/10 px-3 py-2 text-xs">
                <div className="flex items-center gap-2 min-w-0">
                  <span className="text-base">{currentTier.emoji}</span>
                  <div className="truncate">
                    <span className="font-bold text-white text-xs">{currentTier.tierName}</span>
                    <span className="text-[10px] text-white/50 block">Margen {currentTier.markup} ({currentTier.savings})</span>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => setShowTierModal(true)}
                  className="flex-shrink-0 text-[11px] font-bold text-accent bg-accent/10 border border-accent/20 px-2 py-0.5 rounded-lg hover:bg-accent/20 transition-colors"
                >
                  Detalles ›
                </button>
              </div>

              {err && (
                <div className="rounded-xl border border-red-500/20 bg-red-500/10 p-2.5 text-xs text-red-300 flex items-center gap-2">
                  <AlertTriangle className="h-4 w-4 flex-shrink-0" />
                  <span>{err}</span>
                </div>
              )}

              {/* Botón de Pago Principal */}
              <button
                type="button"
                data-tour="topup-pay-btn"
                onClick={() => createInvoice()}
                disabled={loading || optionsLoading || !!optionsError || selectedAmount <= 0 || !payCurrency || !payNetwork}
                className="w-full rounded-2xl bg-accent py-3.5 px-4 text-sm font-black text-bg hover:bg-accent/90 disabled:opacity-50 transition-all flex items-center justify-center gap-2 shadow-lg shadow-accent/20 active:scale-[0.98]"
              >
                {loading ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    <span>Generando orden OxaPay...</span>
                  </>
                ) : (
                  <>
                    <Zap className="h-4 w-4" />
                    <span>{payLabel}</span>
                  </>
                )}
              </button>
            </>
          ) : (
            <div className="space-y-3 pt-1">
              <div className="rounded-2xl border border-accent/30 bg-accent/5 p-4 text-center">
                <span className="text-[11px] font-bold uppercase tracking-wider text-white/50">Envía exactamente</span>
                <div className="mt-1 text-2xl sm:text-3xl font-black text-white">
                  {invoice.pay_amount} <span className="text-accent text-lg">{invoice.pay_currency}</span>
                </div>
                <p className="mt-1 text-xs font-bold text-white/70">Red: <span className="text-accent">{invoice.network}</span></p>
                <div className={`mt-2 inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-bold ${secondsLeft === 0 ? 'border-red-500/30 bg-red-500/15 text-red-200' : 'border-yellow-500/30 bg-yellow-500/20 text-yellow-300'}`}>
                  <Clock className="h-3 w-3" />
                  <span>{secondsLeft === 0 ? 'Esta orden venció' : `${status === 'paying' ? 'Pago detectado, esperando red' : 'Esperando pago'}${secondsLeft !== null ? ` · vence en ${formatTimeLeft(secondsLeft)}` : ''}`}</span>
                </div>
              </div>

              {invoice.qr_code && (
                <div className="mx-auto grid w-fit place-items-center rounded-2xl bg-white p-2 shadow-lg shadow-black/30">
                  <img src={invoice.qr_code} alt="QR de pago" className="h-40 w-40 rounded-lg" />
                </div>
              )}

              <div className="rounded-2xl border border-white/10 bg-card p-3">
                <p className="text-[10px] font-bold uppercase tracking-wider text-white/45">Dirección de destino</p>
                <p className="mt-1 break-all select-text font-mono text-xs leading-relaxed text-white/90">{invoice.address}</p>
                <button type="button" onClick={copyPaymentAddress} className="mt-2 flex w-full items-center justify-center gap-1.5 rounded-xl bg-white/10 px-3 py-2 text-xs font-bold text-white transition hover:bg-white/15 active:scale-[0.98]">
                  {copied ? <Check className="h-4 w-4 text-accent" /> : <Copy className="h-4 w-4" />}
                  {copied ? 'Dirección copiada' : 'Copiar dirección'}
                </button>
                {invoice.memo && <p className="mt-2 rounded-lg border border-amber-300/20 bg-amber-300/10 p-2 text-xs text-amber-100">Memo/Destino: <span className="select-text font-mono font-bold">{invoice.memo}</span></p>}
              </div>

              <div className="rounded-xl border border-amber-400/20 bg-amber-400/10 p-3 text-xs leading-relaxed text-amber-100/90">
                Envía solamente <strong>{invoice.pay_currency}</strong> por la red <strong>{invoice.network}</strong>. No cierres esta pantalla hasta que se acredite el saldo.
              </div>

              {err && <div className="rounded-xl border border-red-500/20 bg-red-500/10 p-2.5 text-xs text-red-300">{err}</div>}

              <button
                type="button"
                onClick={() => checkPayment()}
                disabled={checking || secondsLeft === 0}
                className="w-full rounded-2xl bg-accent py-3 px-4 text-sm font-black text-bg transition-all hover:bg-accent/90 disabled:opacity-50 active:scale-[0.98]"
              >
                <span className="inline-flex items-center justify-center gap-2">{checking ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCcw className="h-4 w-4" />}{checking ? 'Verificando en blockchain…' : 'Ya pagué / Verificar estado'}</span>
              </button>
              <button type="button" onClick={() => { setInvoice(null); setStatus(null); setErr(null); }} className="w-full py-1 text-center text-xs text-white/45 transition hover:text-white/70">Cambiar monto o red</button>
            </div>
          )}
        </div>
      </div>

      {paymentSelector && !invoice && (
        <div className="fixed inset-0 z-[1000000] flex items-end justify-center bg-black/75 p-3 backdrop-blur-sm sm:items-center" onClick={(e) => e.target === e.currentTarget && setPaymentSelector(null)}>
          <div role="dialog" aria-modal="true" aria-label={paymentSelector === 'currency' ? 'Seleccionar moneda' : 'Seleccionar red'} className="w-full max-w-md rounded-2xl border border-white/10 bg-[#11171e] p-4 shadow-2xl">
            <div className="mb-3 flex items-center justify-between gap-3">
              <div><p className="text-sm font-black text-white">{paymentSelector === 'currency' ? 'Selecciona moneda' : `Red para ${payCurrency}`}</p><p className="mt-0.5 text-[11px] text-white/45">Solo se muestran opciones habilitadas por OxaPay.</p></div>
              <button type="button" onClick={() => setPaymentSelector(null)} className="grid h-9 w-9 place-items-center rounded-full bg-white/10 text-white/70 transition hover:bg-white/15"><X className="h-4 w-4" /></button>
            </div>
            <div className={`max-h-[55vh] overflow-y-auto pr-1 [scrollbar-width:thin] ${paymentSelector === 'currency' ? 'grid grid-cols-3 gap-2 sm:grid-cols-4' : 'grid grid-cols-2 gap-2'}`}>
              {(paymentSelector === 'currency' ? paymentOptions : availableNetworks).map((option) => {
                const value = paymentSelector === 'currency' ? option.symbol : option.network
                const selected = paymentSelector === 'currency' ? value === payCurrency : value === payNetwork
                const title = paymentSelector === 'currency' ? option.symbol : option.name
                return <button key={value} type="button" onClick={() => {
                  if (paymentSelector === 'currency') setPayCurrency(value)
                  else setPayNetwork(value)
                  setErr(null)
                  setPaymentSelector(null)
                }} className={`relative flex min-h-16 items-center gap-2 overflow-hidden rounded-xl border p-2 text-left transition active:translate-y-[2px] ${selected ? 'border-accent/70 bg-gradient-to-b from-emerald-300/20 to-emerald-900/20 text-white shadow-[inset_0_1px_1px_rgba(255,255,255,.2),0_3px_0_#057544]' : 'border-white/10 bg-white/[.045] text-white/75 shadow-[inset_0_1px_1px_rgba(255,255,255,.06),0_3px_0_#050709]'}`}>
                  <PaymentAssetIcon symbol={paymentSelector === 'currency' ? value : ''} network={paymentSelector === 'network' ? value : ''} className="h-7 w-7" />
                  <span className="min-w-0"><span className="block truncate text-xs font-black">{title}</span>{paymentSelector === 'currency' && <span className="block truncate text-[9px] text-white/45">{option.name}</span>}</span>
                  {selected && <Check className="ml-auto h-4 w-4 shrink-0 text-accent" />}
                </button>
              })}
            </div>
          </div>
        </div>
      )}

      {/* Modal Secundario de Escala de Beneficios / Descuentos */}
      {showTierModal && (
        <ResellerPricingModal
          onClose={() => setShowTierModal(false)}
          onSelectAmount={(amt) => {
            setAmount(String(amt))
            setShowTierModal(false)
            setInvoice(null)
          }}
        />
      )}
    </>
  )
}

// ════════════════════════════════════════════════════════



function getAccountImages(product) {
  const images = Array.isArray(product?.account_images) ? product.account_images : []
  const all = [...images, product?.icon_url].filter(Boolean)
  return [...new Set(all)]
}

function AccountImageGallery({ product }) {
  if (product.category !== 'game_account') return null
  const images = getAccountImages(product)
  const [selected, setSelected] = useState(0)
  const [viewerOpen, setViewerOpen] = useState(false)
  const current = images[selected] || images[0]
  if (!images.length) return null
  const move = (delta) => setSelected((selected + delta + images.length) % images.length)
  return (
    <div className="mb-4">
      <button onClick={() => setViewerOpen(true)} className="block w-full overflow-hidden rounded-xl border border-white/10 bg-card active:scale-[0.995]">
        <span className="block relative aspect-video bg-black/30">
          <OptimizedImage src={current} className="h-full w-full object-cover" alt={product.name} eager />
          <span className="block absolute bottom-2 right-2 rounded-full bg-black/65 px-2 py-1 text-[10px] font-bold text-white/80">{selected + 1}/{images.length}</span>
        </span>
      </button>
      {images.length > 1 && (
        <div className="mt-2 flex gap-2 overflow-x-auto pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          {images.map((url, index) => (
            <button key={url} onClick={() => setSelected(index)} className={(index === selected ? 'border-accent' : 'border-white/10') + ' h-14 w-14 flex-shrink-0 overflow-hidden rounded-lg border'}>
              <OptimizedImage src={url} className="h-full w-full object-cover" alt="" />
            </button>
          ))}
        </div>
      )}
      {viewerOpen && (
        <div className="fixed inset-0 z-[90] flex flex-col bg-black/95 p-3">
          <div className="mb-3 flex items-center justify-between gap-3 text-white">
            <p className="truncate text-sm font-bold">{product.name}</p>
            <button onClick={() => setViewerOpen(false)} className="flex h-10 w-10 items-center justify-center rounded-full bg-white/10"><X className="h-5 w-5" /></button>
          </div>
          <div className="relative flex min-h-0 flex-1 items-center justify-center">
            <OptimizedImage src={current} className="max-h-full max-w-full object-contain" alt={product.name} eager />
            {images.length > 1 && <button onClick={() => move(-1)} className="absolute left-1 flex h-11 w-11 items-center justify-center rounded-full bg-white/10"><ArrowLeft className="h-5 w-5" /></button>}
            {images.length > 1 && <button onClick={() => move(1)} className="absolute right-1 flex h-11 w-11 items-center justify-center rounded-full bg-white/10"><ChevronRight className="h-5 w-5" /></button>}
          </div>
          {images.length > 1 && <p className="mt-3 text-center text-xs text-white/55">{selected + 1} de {images.length}</p>}
        </div>
      )}
    </div>
  )
}

function AccountDetailsPanel({ product }) {
  if (product.category !== 'game_account') return null
  const details = [
    ['Juego', product.account_game],
    ['Plataforma', product.account_platform],
    ['Región', product.account_region],
    ['Nivel', product.account_level],
    ['Rango', product.account_rank],
    ['Moneda disponible', product.account_currency],
    ['Método de acceso', product.account_access_method],
    ['Estado', product.account_status === 'sold' ? 'Vendida' : product.account_status === 'inactive' ? 'Inactiva' : 'Disponible'],
    ['Garantía', product.account_warranty],
  ].filter(([, value]) => String(value || '').trim())
  return (
    <div className="mb-4 space-y-3">
      <div className="card border-accent/20 p-3">
        <p className="mb-2 flex items-center gap-2 text-sm font-bold"><User className="h-4 w-4 text-accent" />Información de la cuenta</p>
        <div className="grid grid-cols-2 gap-2 text-xs">
          {details.map(([label, value]) => <div key={label} className="rounded-lg bg-bg p-2"><p className="text-white/35">{label}</p><p className="mt-0.5 font-semibold text-white/80">{value}</p></div>)}
        </div>
        {product.account_items && <div className="mt-2 rounded-lg bg-bg p-2 text-xs"><p className="text-white/35">Skins o artículos importantes</p><p className="mt-1 whitespace-pre-line text-white/75">{product.account_items}</p></div>}
      </div>
      <div className="rounded-xl border border-yellow-400/20 bg-yellow-400/10 p-3 text-xs leading-relaxed text-yellow-100/85">
        <p className="font-bold">Instrucciones de compra:</p>
        <ol className="mt-2 list-decimal space-y-1 pl-4">
          <li>Revisa todos los detalles de la cuenta.</li><li>Verifica juego, región, nivel, rango y método de acceso.</li><li>Confirma que la cuenta cumple con lo que necesitas.</li><li>Realiza la compra usando tu saldo disponible.</li><li>El pedido quedará pendiente de entrega manual.</li><li>El administrador enviará los datos de acceso cuando el pedido sea revisado.</li><li>Después de recibir la cuenta, revisa el acceso lo antes posible.</li>
        </ol>
      </div>
    </div>
  )
}

function ManualBuyModal({ product: initialProduct, onClose, onBought, buyResult, me, onLoginRequired, onOpenStore }) {
  const [product, setProduct] = useState(initialProduct)
  useEffect(() => {
    setProduct(initialProduct)
  }, [initialProduct])

  async function handleSwitchOffer(offer, currentSelectedOpt = null) {
    if (!offer?.id) return
    try {
      const full = await api.manualProduct(offer.id)
      if (full) {
        setProduct(full)
        const optTarget = (currentSelectedOpt?.name || selectedOption?.name || '').toLowerCase().trim()
        let matchingOpt = null
        if (optTarget && full.options?.length) {
          matchingOpt = full.options.find(o => o.name && o.name.toLowerCase().trim() === optTarget) ||
                        full.options.find(o => o.name && (optTarget.includes(o.name.toLowerCase().trim()) || o.name.toLowerCase().trim().includes(optTarget)))
        }
        setSelectedOptionId(matchingOpt?.id || full.options?.[0]?.id || null)
      }
    } catch {
      setProduct(prev => ({
        ...prev,
        ...offer,
        id: offer.id,
        name: offer.name,
        price: offer.price,
        delivery_time: offer.delivery_time,
        account_warranty: offer.account_warranty,
        seller_store: offer.seller_store
      }))
    }
  }

  const activeOptions = (product.options || []).filter(o => o.stock !== 0)
  const activeFields = (product.fields || []).filter(f => f.is_required || f.is_active !== false)
  const [selectedOptionId, setSelectedOptionId] = useState(activeOptions[0]?.id || null)
  const [customerData, setCustomerData] = useState({})
  const [buying, setBuying] = useState(false)
  const [err, setErr] = useState(null)
  const [cupSettings, setCupSettings] = useState(null)
  const [cupSettingsError, setCupSettingsError] = useState('')
  const [pendingCupOrder, setPendingCupOrder] = useState(null)
  const [paymentMethod, setPaymentMethod] = useState('balance')
  const [cupReference, setCupReference] = useState('')
  const [proofFile, setProofFile] = useState(null)
  const [proofPreview, setProofPreview] = useState(null)
  const [copiedField, setCopiedField] = useState(null)
  const [cupSuccess, setCupSuccess] = useState(null)
  const descriptionRef = useRef(null)
  const instructionsRef = useRef(null)
  const reviewsRef = useRef(null)
  const selectedOption = activeOptions.find(o => o.id === selectedOptionId)
  const displayPrice = selectedOption ? selectedOption.price : product.price
  const shareLink = `${window.location.origin}${window.location.pathname}?manual_product=${product.id}`
  const rewardCampaign = product.referral_campaign
  const [showShare, setShowShare] = useState(false)
  const [showDripHelp, setShowDripHelp] = useState(false)
  const [rewardShareLink, setRewardShareLink] = useState('')
  const [loadingRewardLink, setLoadingRewardLink] = useState(false)
  const displayShareLink = rewardShareLink || shareLink

  const loadCupSettings = async () => {
    setCupSettingsError('')
    try {
      const res = await api.cupPaymentSettings()
      setCupSettings(res?.enabled ? res : null)
    } catch (error) {
      setCupSettings(null)
      setCupSettingsError(error?.message || 'Error temporal al cargar la configuración de CUP.')
    }
  }

  useEffect(() => { loadCupSettings() }, [])

  useEffect(() => {
    if (!proofFile) {
      setProofPreview(null)
      return
    }
    const url = URL.createObjectURL(proofFile)
    setProofPreview(url)
    return () => URL.revokeObjectURL(url)
  }, [proofFile])

  function handleCopy(text, field) {
    if (!text) return
    navigator.clipboard?.writeText(text)
    setCopiedField(field)
    setTimeout(() => setCopiedField(null), 2000)
  }

  const cardRate = Number(cupSettings?.transfer_rate) || 0
  const mobileRate = Number(cupSettings?.mobile_rate) || 0
  const numericDisplayPrice = Number(displayPrice || 0)
  const cardCupAmount = Math.round((numericDisplayPrice * cardRate) / 10) * 10
  const mobileCupAmount = Math.round((numericDisplayPrice * mobileRate) / 10) * 10
  const cardEnabled = Boolean(cupSettings?.enabled && cupSettings?.methods?.cup_card_transfer?.enabled && cupSettings?.card_number)
  const mobileEnabled = Boolean(cupSettings?.enabled && cupSettings?.methods?.cup_mobile_balance?.enabled && cupSettings?.mobile_destination_number)
  const hasCupMethods = cardEnabled || mobileEnabled

  async function openShareModal() {
    if (rewardCampaign) {
      if (me?.is_guest) { if (typeof onLoginRequired === 'function') onLoginRequired(); return }
      setLoadingRewardLink(true)
      try {
        const data = await api.referralProductLink(product.id)
        if (data?.url) setRewardShareLink(data.url)
      } catch (e) {
        setErr(e.message)
      } finally {
        setLoadingRewardLink(false)
      }
    }
    setShowShare(true)
  }

  async function handleBuy() {
    if (buying) return
    if (me?.is_guest) { if (typeof onLoginRequired === 'function') onLoginRequired(); return }
    if (activeOptions.length > 0 && !selectedOptionId) { setErr('Selecciona una opción'); return }
    const missing = activeFields.find(f => f.is_required && !String(customerData[f.id] || '').trim())
    if (missing) { setErr(`Completa: ${missing.label}`); return }

    if (paymentMethod === 'balance') {
      const balance = Number(me?.balance || 0)
      if (balance < numericDisplayPrice) {
        setErr(`Saldo USDT insuficiente ($${balance.toFixed(2)} USDT). Recarga saldo o selecciona pagar por Transferencia CUP o Saldo Móvil abajo.`)
        return
      }
      setBuying(true); setErr(null)
      try {
        const res = await api.buyManualProduct(product.id, selectedOptionId, customerData, getProductReferral(product.id))
        onBought(res)
      } catch (e) { setErr(e.message); setBuying(false) }
      return
    }

    if (!proofFile) {
      setErr('Debes adjuntar la captura del comprobante de transferencia para verificar tu pago.')
      return
    }
    setBuying(true); setErr(null)
    try {
      if (!cupReference.trim()) {
        throw new Error(paymentMethod === 'cup_mobile_balance' ? 'Escribe el número de teléfono desde el que enviaste el saldo.' : 'Escribe el número de transacción de tu comprobante.')
      }
      const orderRes = pendingCupOrder || await api.createManualCupOrder({
        product_id: product.id,
        option_id: selectedOptionId,
        customer_data: customerData,
        payment_method: paymentMethod,
        referral_code: getProductReferral(product.id),
      })
      if (!orderRes?.order_id) throw new Error('No se pudo generar la orden CUP')
      setPendingCupOrder(orderRes)
      await api.uploadCupPaymentProof(orderRes.order_id, cupReference, proofFile)
      setPendingCupOrder(null)
      setCupSuccess({
        order_id: orderRes.order_id,
        product: orderRes.product || product.name,
        amount_cup: orderRes.amount_cup,
        payment_method: paymentMethod,
      })
    } catch (e) {
      setErr(pendingCupOrder ? `El pedido #${pendingCupOrder.order_id} ya fue creado. Corrige el comprobante o la conexión y vuelve a enviarlo; no se generará otro pedido.` : e.message)
    } finally {
      setBuying(false)
    }
  }

  const jumpTo = (ref) => ref.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  // Local cacheBust removed

  return (
    <div className="fixed inset-0 z-50 bg-bg flex justify-center">
      {showShare && (
        <ShareProductModal
          shareLink={displayShareLink}
          productName={product.name}
          onClose={() => setShowShare(false)}
        />
      )}
      <div className="relative h-screen w-full max-w-lg overflow-hidden bg-bg">
        {buyResult ? (
          <div className="flex h-full flex-col justify-center p-6 text-center">
            <CircleCheck className="mx-auto mb-4 h-12 w-12 text-green-400" aria-hidden="true" />
            <h3 className="text-xl font-bold mb-2">¡Pedido creado!</h3>
            <div className="card p-4 mb-4 flex items-center gap-3 text-left">
              {product.icon_url ? (
                <OptimizedImage
                  src={`${storeAssetUrl(product.icon_url)}?v=${cacheBust}`}
                  alt=""
                  className="w-14 h-14 rounded-xl object-cover flex-shrink-0"
                  eager
                />
              ) : (
                <div className="w-14 h-14 rounded-xl bg-bg flex items-center justify-center flex-shrink-0">
                  <Gamepad2 className="h-6 w-6 text-white/40" />
                </div>
              )}
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold truncate">{buyResult.product}</p>
                <p className="text-lg font-black text-accent mt-0.5">${buyResult.price?.toFixed(2)} USDT</p>
                <p className="text-[10px] text-white/40 mt-1">Pedido #{buyResult.order_id}</p>
              </div>
            </div>
            <p className="text-sm text-white/60 mb-6">{buyResult.message}</p>
            <button onClick={onClose}
              className="w-full py-3 rounded-xl bg-gradient-to-r from-accent to-accent2 font-bold active:scale-95">
              Entendido
            </button>
          </div>
        ) : cupSuccess ? (
          <CupOrderSuccessView order={cupSuccess} onClose={onClose} />
        ) : (
          <>
            <div className="h-full overflow-y-auto pb-28">
              <div className="relative">
                {product.icon_url ? (
                  <div className="h-56 w-full bg-card">
                    <OptimizedImage src={`${product.icon_url}?v=${cacheBust}`} className="h-full w-full object-cover" alt={product.name} eager />
                    <div className="absolute inset-0 bg-gradient-to-t from-bg via-transparent to-transparent" />
                  </div>
                ) : (
                  <div className="h-40 w-full bg-gradient-to-br from-purple-500/20 to-accent/20 flex items-center justify-center">
                    <CategoryIcon category={product.category} className="h-14 w-14 text-white/70" />
                  </div>
                )}
                <button onClick={onClose}
                  className="absolute left-3 top-3 h-9 w-9 rounded-full bg-black/55 flex items-center justify-center text-white/80 active:scale-95">
                  ✕
                </button>
                <button
                  onClick={openShareModal}
                  aria-label={rewardCampaign ? "Compartir y ganar" : "Compartir producto"}
                  className="absolute right-3 top-3 flex items-center gap-1.5 rounded-full px-3 py-2 text-xs font-semibold active:scale-95 transition-all"
                  style={{
                    background: 'linear-gradient(135deg, rgba(99,102,241,0.75), rgba(139,92,246,0.75))',
                    backdropFilter: 'blur(4px)',
                    border: '1px solid rgba(139,92,246,0.5)',
                    color: '#e9d5ff'
                  }}
                >
                  {loadingRewardLink ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Share2 className="h-3.5 w-3.5" />}
                  <span>{rewardCampaign ? 'Ganar' : 'Compartir'}</span>
                </button>
              </div>

              <div className="p-5">
                <div className="mb-4">
                  <h3 className="text-2xl font-bold leading-tight">{product.name}</h3>
                  <p className="mt-2 text-xs text-white/50">
                    <span className="inline-flex items-center gap-1"><CategoryIcon category={product.category} className="h-3.5 w-3.5" />{categoryLabel(product.category)}</span>
                    {deliveryTypeLabel(product.delivery_type, product.category) !== categoryLabel(product.category) && (
                      <> · {deliveryTypeLabel(product.delivery_type, product.category)}</>
                    )}
                  </p>
                </div>

                {(selectedOption?.delivery_time || product.delivery_time) && (
                  <div className="mb-2.5 flex items-center gap-2 rounded-xl border border-accent/25 bg-accent/10 px-3 py-2 text-xs font-semibold text-accent">
                    <Clock className="h-4 w-4 shrink-0 text-accent" />
                    <span>Tiempo estimado de entrega: <strong className="text-white font-bold">{selectedOption?.delivery_time || product.delivery_time}</strong></span>
                  </div>
                )}

                {/* Indicador de Horario del Vendedor */}
                {product.seller_store?.schedule && !product.seller_store.schedule.is_open_now ? (
                  <div className="mb-3 rounded-2xl border border-amber-500/35 bg-amber-500/15 p-3.5 text-xs text-amber-200 flex items-start gap-3 shadow-md animate-fadeIn">
                    <Moon className="h-5 w-5 text-amber-400 flex-shrink-0 mt-0.5" />
                    <div>
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="font-extrabold text-amber-100">Vendedor fuera de horario de atención</span>
                        <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-500/25 text-amber-300 border border-amber-500/30">
                          Abre {product.seller_store.schedule.time_start_formatted}
                        </span>
                      </div>
                      <p className="text-[11px] text-amber-200/90 mt-1 leading-relaxed">
                        Horario de la tienda: <b>{product.seller_store.schedule.time_start_formatted} – {product.seller_store.schedule.time_end_formatted}</b>. Puedes realizar tu compra con total confianza; tu orden será procesada y entregada a primera hora en cuanto el vendedor inicie su turno.
                      </p>
                    </div>
                  </div>
                ) : product.seller_store?.schedule?.is_open_now && product.seller_store?.store_slug !== 'oficial' ? (
                  <div className="mb-3 flex items-center gap-2 rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-xs font-semibold text-emerald-300">
                    <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
                    <span>Vendedor en línea y atendiendo ahora ({product.seller_store.schedule.time_start_formatted} – {product.seller_store.schedule.time_end_formatted})</span>
                  </div>
                ) : null}

                <ProductTrustPanel product={product} price={displayPrice} selectedOption={selectedOption} />

                {rewardCampaign && (
                  <div className="mb-4 rounded-xl border border-emerald-400/20 bg-emerald-500/10 p-3">
                    <p className="text-sm font-black text-emerald-300">Comparte y gana ${Number(rewardCampaign.reward_amount_usdt || 0).toFixed(2)} USDT</p>
                    <p className="mt-1 text-xs leading-relaxed text-white/65">Comparte este producto. Si alguien compra desde tu enlace, ganas la recompensa cuando el pedido sea completado.</p>
                    <button onClick={openShareModal} disabled={loadingRewardLink} className="mt-3 w-full rounded-lg bg-emerald-400 px-3 py-2 text-sm font-black text-bg active:scale-95 disabled:opacity-60">
                      {loadingRewardLink ? 'Preparando enlace...' : 'Compartir y ganar'}
                    </button>
                  </div>
                )}

                {/* Comparador de Ofertas Multi-Tienda (GamsGo / G2A Buy Box) */}
                <MultiStoreOffersComparison
                  productId={product.id}
                  searchKeyword={product.account_game || product.name}
                  currentProductId={product.id}
                  onSelectOffer={handleSwitchOffer}
                  onOpenStore={onOpenStore}
                  sellerStore={product.seller_store}
                  currentPrice={displayPrice}
                  selectedOption={selectedOption}
                />

                <AccountImageGallery product={product} />
                <AccountDetailsPanel product={product} />

                {activeOptions.length > 0 && (
                  <div className="mb-4">
                    <div className="mb-2 flex items-center justify-between">
                      <label className="block text-xs font-bold text-white/70">
                        Selecciona tu paquete:
                      </label>
                      <span className="text-[10px] text-white/40">{activeOptions.length} opciones disponibles</span>
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                      {activeOptions.map((opt) => {
                        const isSelected = selectedOptionId === opt.id
                        return (
                          <button
                            key={opt.id}
                            type="button"
                            onClick={() => { setSelectedOptionId(opt.id); setErr(null) }}
                            className={`group relative flex flex-col justify-between p-2.5 rounded-xl border text-left transition-all active:scale-[0.98] ${
                              isSelected
                                ? 'border-accent bg-accent/20 shadow-md shadow-accent/15 ring-1 ring-accent'
                                : 'border-white/10 bg-card hover:border-white/25 hover:bg-white/5'
                            }`}
                          >
                            <div className="flex items-center justify-between gap-1 mb-1">
                              <span className={`text-xs font-black truncate ${isSelected ? 'text-accent' : 'text-white'}`}>
                                {opt.name}
                              </span>
                              {isSelected && <Check className="h-3.5 w-3.5 text-accent shrink-0" />}
                            </div>
                            <div className="flex items-baseline justify-between gap-1 mt-1">
                              <span className="text-xs font-black text-accent">
                                ${Number(opt.price || 0).toFixed(2)} USDT
                              </span>
                              {opt.delivery_time && (
                                <span className="text-[9px] text-white/40 truncate">
                                  ⏱️ {opt.delivery_time}
                                </span>
                              )}
                            </div>
                            {opt.stock >= 0 && (
                              <span className="mt-1 text-[9px] text-white/40">
                                Stock: {opt.stock}
                              </span>
                            )}
                          </button>
                        )
                      })}
                    </div>

                    {selectedOption && (
                      <div className="mt-2.5 rounded-xl border border-accent/20 bg-accent/10 p-2.5 text-xs text-white/75 flex items-center justify-between">
                        <div>
                          <p className="font-bold text-white text-xs">{selectedOption.name}</p>
                          {(selectedOption.delivery_time || product.delivery_time) && (
                            <p className="text-[11px] text-emerald-400 font-semibold mt-0.5">⏱️ Entrega estimada: {selectedOption.delivery_time || product.delivery_time}</p>
                          )}
                        </div>
                        <p className="text-sm font-black text-accent">${Number(selectedOption.price || 0).toFixed(2)} USDT</p>
                      </div>
                    )}
                  </div>
                )}

                {activeFields.length > 0 && (
                  <div className="mb-4">
                    <p className="mb-2 text-xs font-semibold text-white/50">Datos para entregar tu pedido</p>
                    <div className="space-y-2">
                      {activeFields.map(field => (
                        <div key={field.id}>
                          <label className="mb-1 block text-xs text-white/50">
                            {field.label}{field.is_required ? ' *' : ''}
                          </label>
                          <input
                            value={customerData[field.id] || ''}
                            onChange={(e) => { setCustomerData(prev => ({ ...prev, [field.id]: e.target.value })); setErr(null) }}
                            type={field.field_type === 'number' ? 'number' : field.field_type === 'phone' ? 'tel' : 'text'}
                            inputMode={field.field_type === 'phone' ? 'tel' : field.field_type === 'number' ? 'decimal' : 'text'}
                            placeholder={field.placeholder || field.label}
                            className="w-full rounded-xl border border-white/10 bg-card px-3 py-3 text-sm outline-none focus:border-accent"
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                <PaymentMethodSection
                  isGuest={Boolean(me?.is_guest)}
                  onLoginRequired={onLoginRequired}
                  paymentMethod={paymentMethod}
                  setPaymentMethod={setPaymentMethod}
                  priceUsdt={numericDisplayPrice}
                  cupSettings={cupSettings}
                  cupSettingsError={cupSettingsError}
                  onRetryCupSettings={loadCupSettings}
                  userBalance={Number(me?.balance || 0)}
                  cardCupAmount={cardCupAmount}
                  mobileCupAmount={mobileCupAmount}
                  cardEnabled={cardEnabled}
                  mobileEnabled={mobileEnabled}
                  hasCupMethods={hasCupMethods}
                  cupReference={cupReference}
                  setCupReference={setCupReference}
                  proofFile={proofFile}
                  setProofFile={setProofFile}
                  proofPreview={proofPreview}
                  handleCopy={handleCopy}
                  copiedField={copiedField}
                />

                <div className="sticky top-0 z-10 mb-4 grid grid-cols-3 gap-2 bg-bg/95 py-2 backdrop-blur">
                  <button onClick={() => jumpTo(descriptionRef)} className="rounded-lg border border-white/10 bg-card px-2 py-2 text-xs font-semibold text-white/75 active:scale-95">Descripción</button>
                  <button onClick={() => jumpTo(instructionsRef)} className="rounded-lg border border-white/10 bg-card px-2 py-2 text-xs font-semibold text-white/75 active:scale-95">Instrucciones</button>
                  <button onClick={() => jumpTo(reviewsRef)} className="rounded-lg border border-white/10 bg-card px-2 py-2 text-xs font-semibold text-white/75 active:scale-95">Valoraciones</button>
                </div>

                <div ref={descriptionRef} className="scroll-mt-16 mb-4">
                  <p className="mb-2 flex items-center gap-2 text-sm font-semibold"><FileText className="h-4 w-4 text-accent" />Descripción</p>
                  <div className="card p-3">
                    {product.description ? (
                      <p className="text-sm text-white/70 whitespace-pre-line"><Linkify>{product.description}</Linkify></p>
                    ) : (
                      <p className="text-sm text-white/40">Este producto no tiene descripción adicional.</p>
                    )}
                  </div>
                </div>

                <div ref={instructionsRef} className="scroll-mt-16 mb-4">
                  <p className="mb-2 flex items-center gap-2 text-sm font-semibold"><ClipboardList className="h-4 w-4 text-yellow-300" />Instrucciones</p>
                  <div className="card border-yellow-500/20 p-3">
                    {product.instructions ? (
                      <p className="text-sm text-white/60 whitespace-pre-line"><Linkify>{product.instructions}</Linkify></p>
                    ) : (
                      <p className="text-sm text-white/40">No hay instrucciones especiales para este producto.</p>
                    )}
                  </div>
                </div>

                {product.category === 'game_account' && (
                  <div className="mb-4">
                    <p className="mb-2 flex items-center gap-2 text-sm font-semibold"><ShieldAlert className="h-4 w-4 text-yellow-300" />Términos importantes</p>
                    <div className="card border-yellow-500/20 p-3 text-sm text-white/65">
                      <p className="whitespace-pre-line"><Linkify>{product.account_terms || `El cliente debe revisar cuidadosamente toda la información de la cuenta antes de comprar.

Una vez entregados correctamente los datos de acceso, no se aceptan reembolsos, salvo que la cuenta no funcione al momento de la entrega.

La garantía solo cubre problemas de acceso inicial durante el período indicado en el producto.

No se aceptan reclamaciones por cambios realizados por el cliente después de recibir la cuenta.

Algunos juegos pueden tener restricciones sobre la compra o venta de cuentas. El cliente acepta comprar bajo su responsabilidad.

Francho Shop no vende cuentas robadas, hackeadas, recuperadas, baneadas o con datos personales de terceros.`}</Linkify></p>
                    </div>
                  </div>
                )}

                <div ref={reviewsRef} className="scroll-mt-16 mb-6">
                  <PublicReviewsPanel manualProductId={product.id} me={me} onLoginRequired={onLoginRequired} />
                </div>

                {err && <p className="mb-6 rounded-lg border border-red-500/20 bg-red-500/10 p-3 text-center text-sm text-red-300">{err}</p>}
              </div>
            </div>

            <div className="fixed inset-x-0 bottom-0 z-[60] mx-auto max-w-lg border-t border-white/10 bg-bg/95 p-3 pb-[calc(env(safe-area-inset-bottom)+12px)] shadow-2xl shadow-black/50 backdrop-blur">
              <div className="flex items-center gap-3">
                <button onClick={onClose}
                  className="h-12 w-12 flex-shrink-0 rounded-xl border border-red-400/30 bg-red-500/15 text-lg font-bold text-red-200 active:scale-95">
                  X
                </button>
                <button
                  onClick={openShareModal}
                  aria-label={rewardCampaign ? "Compartir y ganar" : "Compartir"}
                  className="h-12 w-12 flex-shrink-0 rounded-xl active:scale-95 transition-all"
                  style={{
                    background: 'linear-gradient(135deg, rgba(99,102,241,0.25), rgba(139,92,246,0.25))',
                    border: '1px solid rgba(139,92,246,0.4)'
                  }}
                >
                  <Share2 className="h-5 w-5 mx-auto text-violet-400" />
                </button>
                <button
                  onClick={me?.is_guest ? onLoginRequired : handleBuy}
                  disabled={!me?.is_guest && (buying || (paymentMethod !== 'balance' && (!proofFile || !cupReference.trim())))}
                  className="min-w-0 flex-1 rounded-xl bg-gradient-to-r from-accent to-accent2 px-3 py-3 font-bold active:scale-95 disabled:opacity-50 text-bg">
                  {me?.is_guest ? (
                    <span key="login_req" className="inline-flex items-center justify-center gap-2">
                      <Lock className="h-5 w-5" />
                      <span>Iniciar sesión para comprar</span>
                    </span>
                  ) : buying ? (
                    <span key="buying" className="inline-flex items-center justify-center gap-2">
                      <Loader2 className="h-4 w-4 animate-spin" />
                      <span>Procesando...</span>
                    </span>
                  ) : paymentMethod === 'cup_card_transfer' ? (
                    <span key="buy_cup_card" className="inline-flex items-center justify-center gap-2">
                      <ShoppingCart className="h-5 w-5" />
                      <span>Enviar comprobante ({cardCupAmount.toLocaleString('es-ES')} CUP)</span>
                    </span>
                  ) : paymentMethod === 'cup_mobile_balance' ? (
                    <span key="buy_cup_mobile" className="inline-flex items-center justify-center gap-2">
                      <ShoppingCart className="h-5 w-5" />
                      <span>Enviar comprobante ({mobileCupAmount.toLocaleString('es-ES')} CUP)</span>
                    </span>
                  ) : (
                    <span key="buy" className="inline-flex items-center justify-center gap-2">
                      <ShoppingCart className="h-5 w-5" />
                      <span>Comprar</span>
                    </span>
                  )}
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  )
}

