  async function handleRevokeDelivery() {
    if (!managingDelivery) return
    const reason = prompt('Motivo de revocación') || 'Entrega revocada'
    setDeliveryActionLoading(true)
    try { await api.revokeDelivery(managingDelivery.id, reason); setManagingDelivery(null); setSelectedOrderDetail(null); await loadData() }
    catch (e) { alert(e.message) }
    setDeliveryActionLoading(false)
  }

  function updatePricingField(gameName, field, value) {
    setPricing(items => items.map(item => item.game_name === gameName ? { ...item, [field]: value } : item))
  }

  async function saveResellerSettings() {
    const amount = Number(String(resellerMinDeposit).replace(',', '.'))
    if (!Number.isFinite(amount) || amount < 50) { alert('El mínimo debe ser 50 USDT o más'); return }
    setSavingResellerSettings(true)
    try {
      const res = await api.updateResellerSettings(amount)
      setResellerMinDeposit(String(res.reseller_min_deposit ?? amount))
    } catch (e) { alert(e.message) }
    setSavingResellerSettings(false)
  }

  async function saveSellerPayoutSettings() {
    const clean = Object.fromEntries(Object.entries(sellerPayoutSettings).map(([k, v]) => [k, Number(String(v).replace(',', '.'))]))
    if (Object.values(clean).some(v => !Number.isFinite(v) || v < 0)) { alert('Todos los valores deben ser números positivos'); return }
    setSavingSellerPayoutSettings(true)
    try {
      const res = await api.updateSellerPayoutSettings(clean)
      setSellerPayoutSettings({
        seller_default_commission_pct: String(res.seller_default_commission_pct ?? clean.seller_default_commission_pct),
        seller_min_platform_fee: String(res.seller_min_platform_fee ?? clean.seller_min_platform_fee),
        seller_hold_days_manual: String(res.seller_hold_days_manual ?? clean.seller_hold_days_manual),
        seller_hold_days_auto: String(res.seller_hold_days_auto ?? clean.seller_hold_days_auto),
        seller_new_days: String(res.seller_new_days ?? clean.seller_new_days),
        seller_new_hold_days: String(res.seller_new_hold_days ?? clean.seller_new_hold_days),
        seller_withdraw_fee_usdt: String(res.seller_withdraw_fee_usdt ?? clean.seller_withdraw_fee_usdt),
      })
    } catch (e) { alert(e.message) }
    setSavingSellerPayoutSettings(false)
  }

  const computedTransferRate = useMemo(() => {
    const p = Number(String(cupSettings.purchase_price_usdt_cup).replace(',', '.'))
    if (!Number.isFinite(p) || p <= 0) return null
    return (p * (1310 / 1100)).toFixed(2)
  }, [cupSettings.purchase_price_usdt_cup])

  const computedMobileRate = useMemo(() => {
    const tr = Number(computedTransferRate)
    const m = Number(String(cupSettings.mobile_credit_value).replace(',', '.'))
    if (!Number.isFinite(tr) || tr <= 0 || !Number.isFinite(m) || m <= 0) return null
    return (tr / m).toFixed(2)
  }, [computedTransferRate, cupSettings.mobile_credit_value])

  async function saveCupSettings() {
    const purchase = Number(String(cupSettings.purchase_price_usdt_cup).replace(',', '.'))
    const mobile = Number(String(cupSettings.mobile_credit_value).replace(',', '.'))
    const maxHours = parseInt(String(cupSettings.max_delivery_hours), 10) || 24

    if (!Number.isFinite(purchase) || purchase <= 0) {
      alert('Ingresa una tasa de compra USDT/CUP válida mayor a 0')
      return
    }
    if (!Number.isFinite(mobile) || mobile <= 0) {
      alert('Ingresa un factor de saldo móvil válido mayor a 0')
      return
    }
    if (cupSettings.card_transfer_enabled && (!cupSettings.card_number?.trim() || !cupSettings.confirmation_number?.trim())) {
      alert('Configura la tarjeta CUP y el teléfono de confirmación antes de activar transferencia bancaria')
      return
    }
    if (cupSettings.mobile_transfer_enabled && !cupSettings.mobile_destination_number?.trim()) {
      alert('Configura el teléfono de destino de saldo móvil antes de activarlo')
      return
    }

    setSavingCupSettings(true)
    try {
      const payload = {
        enabled: !!cupSettings.enabled,
        usdt_purchase_price_cup: String(purchase),
        mobile_credit_value: String(mobile),
        card_transfer_enabled: !!cupSettings.card_transfer_enabled,
        card_number: cupSettings.card_number?.trim() || '',
        confirmation_number: cupSettings.confirmation_number?.trim() || '',
        mobile_transfer_enabled: !!cupSettings.mobile_transfer_enabled,
        mobile_destination_number: cupSettings.mobile_destination_number?.trim() || '',
        max_delivery_hours: maxHours,
      }
      const res = await api.adminCupPaymentSettingsSet(payload)
      if (res) {
        setCupSettingsSuccess(true)
        setTimeout(() => setCupSettingsSuccess(false), 3000)
        if (res.purchase_price_usdt_cup) {
          setCupSettings(prev => ({
            ...prev,
            enabled: !!res.enabled,
            purchase_price_usdt_cup: String(res.purchase_price_usdt_cup),
            mobile_credit_value: String(res.mobile_credit_value),
            transfer_rate: String(res.transfer_rate || ''),
            mobile_rate: String(res.mobile_rate || ''),
            card_number: String(res.card_number || prev.card_number),
            confirmation_number: String(res.confirmation_number || prev.confirmation_number),
            mobile_destination_number: String(res.mobile_destination_number || prev.mobile_destination_number),
            card_transfer_enabled: res.methods?.cup_card_transfer ? !!res.methods.cup_card_transfer.enabled : prev.card_transfer_enabled,
            mobile_transfer_enabled: res.methods?.cup_mobile_balance ? !!res.methods.cup_mobile_balance.enabled : prev.mobile_transfer_enabled,
            max_delivery_hours: Number(res.max_delivery_hours || 24),
          }))
        }
      }
    } catch (e) {
      alert(e.message || 'Error guardando configuración CUP')
    } finally {
      setSavingCupSettings(false)
    }
  }

  async function savePricing(item) {
    const cleanNumber = (value) => {
      if (value === '' || value === null || value === undefined) return null
      const n = Number(String(value).replace(',', '.'))
      return Number.isFinite(n) ? n : null
    }
    setSavingPricing(item.game_name)
    try {
      await api.updateGamePricing({
        game_name: item.game_name,
        retail_markup: cleanNumber(item.retail_markup),
        reseller_markup: cleanNumber(item.reseller_markup),
      })
      await loadData()
    } catch (e) { alert(e.message) }
    setSavingPricing(null)
  }

  async function handleGameImageUpload(item, file) {
    if (!file) return
    if (!file.type?.startsWith('image/')) { alert('Selecciona una imagen válida'); return }
    if (file.size > 5 * 1024 * 1024) { alert('La imagen no puede pasar de 5 MB'); return }
    setSavingGameVisual(item.game_name)
    try {
      const uploadFile = await compressImageForUpload(file)
      const res = await api.uploadIcon(uploadFile)
      updatePricingField(item.game_name, 'icon_url', res.url)
      await api.updateGameIcon({
        game_name: item.game_name,
        emoji: item.emoji || null,
        icon_url: res.url,
        display_name: item.display_name || '',
        sort_order: Number(item.sort_order || 100),
        is_hidden: !!item.is_hidden,
        description: item.description || "",
        instructions: item.instructions || "",
      })
      await loadData()
    } catch (e) { alert(e.message) }
    setSavingGameVisual(null)
  }

  async function saveGameVisual(item) {
    setSavingGameVisual(item.game_name)
    try {
      await api.updateGameIcon({
        game_name: item.game_name,
        emoji: item.emoji || null,
        icon_url: item.icon_url || null,
        display_name: item.display_name || '',
        sort_order: Number(item.sort_order || 100),
        is_hidden: !!item.is_hidden,
        description: item.description || "",
        instructions: item.instructions || "",
      })
      await loadData()
    } catch (e) { alert(e.message) }
    setSavingGameVisual(null)
  }

